INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Acm Sébionex K crème – 40 ml','ACM','Visage','ACM Sebionex K kératorégulatrice Crème 40 ml Soin kératorégulateur matifiant Peaux à imperfections La crèm Sebionex K possède une triple action: - Kératorégulatrice A.H.A: 15% Acide glycolique, Esters d''AHA, Lactate d''ammonium - Apaisante a-bisabolol - Séborégulatrice Nylon-12, Gluconate de zinc

