INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Acm Duolys solaire Spf 50+ – 50 ml','ACM','Solaires','L''écran Solaire Anti-âge SPF50+ d''ACM Duolys est un soin solaire conçu pour les sensibles, claires et sujettes aux intolérances solaires.
Il associe des filtres organiques et des écrans minéraux, dont un extrait de nacre d’eau douce pour préserver votre peau des effets néfastes du soleil.

