-Renouvelez régulièrement.',22000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3760095251578_a0ccf202-512d-40b9-806c-8d99b77c2597.jpg?v=1715763001',10,1,'6728682307759','39909487673519','https://beautymarket.ma/products/acm-duolys-solaire-spf-50-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3760095251578_a0ccf202-512d-40b9-806c-8d99b77c2597.jpg?v=1715763001"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
