INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Apivita Après-shampoing pour Racines Grasses et Pointes Sèches150ml','Apivita','Cheveux','L’Après-shampoing pour Racines Grasses et Pointes Sèches équilibrant est idéal pour les cheveux aux racines grasses et aux pointes sèches grâce à sa texture légère qui laisse les cheveux doux et souples.

- Nourrit et équilibre les cheveux aux racines grasses, grâce aux extraits d’ortie et de propolis.

- Hydrate intensément et répare les pointes sèches et abîmées, grâce au miel de thym et aux protéines de blé.

- Empêche la casse et les pointes fourchues, tout en protégeant des agressions extérieures (pollution de l’air et coiffage), grâce au complexe APISHIELD HS.

- Laisse les cheveux doux, pleins de volume et faciles à coiffer.

L’eau est remplacée par une infusion tonique et anti-âge de romarin bio grec.

Conseils d’utilisation :

Après le shampoing, appliquez l’Après-shampoing sur les mi-longueurs jusqu’aux pointes, laissez agir pendant 2-3 minutes puis rincez abondamment.

Evitez le contact avec les yeux. Pour usage externe uniquement.

Conseils supplémentaires :

- N’appliquez l’après-shampoing que sur les longueurs et les pointes des cheveux, en évitant les racines, puis rincez abondamment.

- Évitez de rincer les cheveux à l’eau chaude, car cela pourrait irriter le cuir chevelu et intensifier l’effet gras.

- Brossez-vous doucement les cheveux (préférez une brosse à poils naturels).

- Pour limiter les dommages, évitez l’utilisation de la chaleur lors du coiffage.',9300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/apivita-apres-shampoing-pour-racines-grasses-et-pointes-seches150ml_ac6aecc7-07c6-4620-8737-52f1b28d4920.jpg?v=1630341533',10,1,'6728689516719','39909505401007','https://beautymarket.ma/products/apivita-apres-shampoing-pour-racines-grasses-et-pointes-seches150ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/apivita-apres-shampoing-pour-racines-grasses-et-pointes-seches150ml_ac6aecc7-07c6-4620-8737-52f1b28d4920.jpg?v=1630341533"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('APIVITA SHAMPOOING NOURRISSANT REPARATEUR OLIVE & MIEL','Apivita','Cheveux','La sécheresse des cheveux est très courante. Elle est causée par les effets néfastes de l’environnement ou les dommages causés par le style. Le shampooing Nourish & Repair nourrit et hydrate intensément, redonnant éclat et éclat perdus. 90% d’origine naturelle',9215,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-38_346a41ac-d8f1-411e-b26f-d38af8b8a4b6.jpg?v=1630341537',10,1,'6728689713327','39909505794223','https://beautymarket.ma/products/apivita-shampooing-nourrissant-reparateur-olive-miel',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-38_346a41ac-d8f1-411e-b26f-d38af8b8a4b6.jpg?v=1630341537"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
