INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Apivita Wine Elixir Huile visage Repulpante 30ml','Apivita','Visage','Une combinaison unique d’huiles légères et d’huiles essentielles, enrichie de puissantes molécules anti-âge, les polyphénols de l’huile de pépins de raisin

