INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Avène - cold cream crème 100 ml','Avène','Visage','Testé en conditions de grand froid, ce soin nutritif à la texture enveloppante et au parfum léger laisse sur la peau un fini doux, non gras et non collant. Grâce au Cold Cream d''Eau Thermale Avène, un mélange traditionnel d''ingrédients issue de la pharmacopée française, la peau est nourrit, protégée et apaisée même en conditions de grand froid. Convient à toute la famille. Visage et corps.

