INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bébé Confort Biberon Natural Comfort En verre 130ml','Bebe Confort','Bébé & Maman','Quel que soit votre choix d’allaitement, sein, biberon exclusif ou encore mixte, Natural Comfort est le biberon Bébé Confort qui répondra parfaitement à vos attentes et sera accepté naturellement par bébé.

