INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BEBEDOR Gobelets Anti Gouttes Poignee +9M 507','Bebedor','Bébé & Maman','Le bac à eau douce aide le bébé à passer du biberon à la tasse. Il est spécialement conçu pour éviter les gouttes. Il se tient facilement grâce à ses poignées. Lavez toutes les pièces séparément avec du savon liquide et de l’eau tiède avant la première utilisation et après chaque utilisation. Bien rincer. sécher à l’air libre. lavé dans le panier supérieur du lave-vaisselle. Il n’est pas utilisé dans le four à micro-ondes.',7125,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/8690683005069_6e2adb58-131c-46a6-af91-62e00151acf8.png?v=1630342200',10,1,'6728723857583','39909561499823','https://beautymarket.ma/products/bebedor-gobelets-anti-gouttes-poignee-9m-507',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/8690683005069_6e2adb58-131c-46a6-af91-62e00151acf8.png?v=1630342200"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bebedor Gobelet Hard spout +6m 250ml 8508','Bebedor','Bébé & Maman','Lors du passage des aliments liquides aux aliments solides, le biberon peut être utilisé comme récipient et les aliments peuvent être facilement pris avec une cuillère. Il peut être bouilli et stérilisé, il peut être entré au micro-ondes sans couvercle ni poignée. Il se remplit facilement grâce à sa large ouverture et peut être utilisé comme récipient pour se nourrir à la cuillère.Une prise facile grâce à ses poignées.',7200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/8690683085085-1_fb8813f8-deaa-4289-81a5-9941904cddfd.jpg?v=1630342202',10,1,'6728723923119','39909561565359','https://beautymarket.ma/products/bebedor-gobelet-hard-spout-6m-250ml-8508',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/8690683085085-1_fb8813f8-deaa-4289-81a5-9941904cddfd.jpg?v=1630342202"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
