INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOCLIN BIO-CLEAN UP PEEILING UNIDOSE 6X5 ml','Bioclin','Cheveux','un soin peeling doux ,assainissant & détoxifiant formulée à base d’extrait d’ortie blanche,

d’acide salicylique et de piroctone Olamine .Favorise l’élimination

des squames et assainit le cuir chevelu et apaise

les démangeaisons et les irritations .

CONSEILS D’UTILISATION:

Mouillez les cheveux, séchez avec une serviette et répartissez le produit uniformément sur le cuir chevelu,

en massant doucement avec vos doigts pendant quelques minutes. Laisser agir 3 à 5 minutes et rincer.

Ensuite, passez au shampooing antipelliculaire Bio-Squam ou un shampooing Bioclin au choix.',10600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/BIO-CLIN-PEELING_118977e7-9490-43b3-b9b4-2746bd735db9.png?v=1630342382',10,1,'6728734441647','39909580406959','https://beautymarket.ma/products/bioclin-bio-clean-up-peeiling-unidose-6x5-ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/BIO-CLIN-PEELING_118977e7-9490-43b3-b9b4-2746bd735db9.png?v=1630342382"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOCOL Menoconcept 30 Comprimes','Biocol','Bien-être','- Action régulatrice hormonale

- Equilibre du SNC, Action antistress et anxiolytique

- Réduction de la perte osseuse

Actions :

- Moins de bouffées de chaleur

- Moins de perte osseuse

- Moins d’anxiété

Ingrédients :

- Extrait de soja, Extrait d’houblon, Vitamine C, Zinc, Vitamine B6, Vitamine B1, Acide folique, Sélénium, Vitamine D3, Vitamine B12

Mode d’emploi

Présentation :

- Boîte de 30 comprimés (2 Blisters de 15 Comprimés)

