INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bioderma Nodé DS+ Shampooing Anti-récidive – 125 ml','Bioderma','Cheveux','La formule exclusive de Nodé DS+ offre une efficacité optimale contre les états pelliculaires sévères. Le complexe breveté DSactive™ garantit une double efficacité grâce à son action biologique sur la cause des squames :

Il limite la prolifération de la levure Malassezia responsable des pellicules.

Il évite la récidive en réduisant la sécrétion de sébum, qui favorise justement le développement de ces levures. Ses puissants agents kérato-régulateurs facilitent l’élimination des pellicules persistantes. Enrichi en agents apaisants, Nodé DS+ soulage instantanément et durablement les démangeaisons du cuir chevelu. Le complexe naturel breveté D.A.F augmente le seuil de tolérance des cuirs chevelus sensibles.

Après 2 mois d’utilisation, les volontaires ont remarqué une réduction de -83 % de l’érythème, une réduction de -78 % des squames et une réduction de -77 % des démangeaisons.*',16500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtswrtret.png?v=1727515289',10,1,'6728739487919','39909589516463','https://beautymarket.ma/products/bioderma-node-ds-shampooing-anti-recidive-125-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/drtswrtret.png?v=1727515289"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
