INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOKERA SHAMPOING ANTI CHUTE 300ml','Biokera','Cheveux','Shampoing Spécifique Chute est un shampoing de traitement spécifique pour aider à régulariser le cycle de croissance et de chute des cheveux. Sa formule aux extraits de ginseng et Gingko Biloba, stimule la regénération des cheveux et régule leur cycle de croissance.

