INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOKERA SHAMPOOING SPÉCIFIQUE GRAS 300ML','Biokera','Cheveux','Shampoing Spécifique Gras est un shampoing idéal pour des cheveux avec des problèmes dans le cycle de production du gras. Sa formule intègre des composés spécifiques pour nettoyer de manière douce et réguler le cycle de production de gras naturel, et elle augmente donc le temps entre les lavages.

