INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOKERA SHAMPOOING SPÉCIFIQUE PELLICULES 1L','Biokera','Cheveux','Shampooing idéal pour les cheveux présentant des problèmes dans le cycle naturelde desquamation du cuir chevelu. Sa formule spécifique à base de zinc et d''huile de lin combine l''action de nettoyer tout en agissant contre les agents responsables des pellicules et en réhydratant la peau et le cuir chevelu.

Empêche l''écaillage.

Idéal pour les cheveux à tendance pelliculaire

Zinc et huile de lin.

 Avantages

Combine l''action de nettoyer tout en agissant contre les agents responsables des pellicules et en réhydratant la peau du cuir chevelu. Prépare la peau et les cheveux à optimiser l''action des autres produits antipelliculaires.',52500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3009.avif?v=1773928055',10,1,'6728762097839','39909633687727','https://beautymarket.ma/products/biokera-shampoing-specifique-pellicules-1l',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/3009.avif?v=1773928055"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOKERA SHAMPOING CHEVEUX TRAITÉS 300ML','Biokera','Cheveux','Shampoing Traités est un shampoing idéal pour des cheveux avec couleur ou ayant reçu des techniques. Sa formule avec huile de macadamia et extrait de baies rouges apporte un plus de nutrition et de conservation de la couleur des cheveux.

Recommandé suite aux périodes d’expositions à la piscine, à la mer, etc.

