INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Biokera Ampoules Traitement intensif Cheveux gras 6Ampoules*10ml','Biokera','Cheveux','Traitement Intensif Gras est une lotion idéale pour des cheveux avec des problèmes dans le cycle de production du gras. Elle maintient les cheveux propres plus longtemps car elle élimine l’excès de gras en conservant ce dont ils ont besoin pour une protection correcte du cheveu. Sa formule avec des protéines et acides aminés évite l’excès de gras.',25000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/AMPOULE-CHEVEUX-GRAS_b231571b-481c-4e29-b31c-a00f5fa1ece1.jpg?v=1630342875',10,1,'6728762523823','39909634277551','https://beautymarket.ma/products/biokera-ampoules-traitement-intensif-cheveux-gras-6ampoules-10ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/AMPOULE-CHEVEUX-GRAS_b231571b-481c-4e29-b31c-a00f5fa1ece1.jpg?v=1630342875"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOKERA TRAITEMENT ANTI-CHUTE VOLUMATEUR 300 ML','Biokera','Cheveux','Traitement Volumateur Chute est une lotion en vaporisateur pour le traitement spécifique de maintenance qui aide à régulariser le cycle de croissance des cheveux. Sa formule contient une combinaison de vitamines, d’actifs revitalisants et d’extrait de ginseng qui augmente la vigueur du bulbe pilaire et stimule le régénération de toute la chevelure.

MODE D’EMPLOI

Appliquez le Traitement Volumateur Chute sur le cuir chevelu et les cheveux. Effectuer un massage en rotations en commençant par la nuque vers le front. Il n’est pas nécessaire de rincer. Procédez au brossage comme d’habitude.',25300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/biokera-traitement-anti-chute-volumateur-300-ml_bba791bd-c975-47df-aee8-ed177237afed.png?v=1630342879',10,1,'6728762753199','39909634506927','https://beautymarket.ma/products/biokera-traitement-anti-chute-volumateur-300-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/biokera-traitement-anti-chute-volumateur-300-ml_bba791bd-c975-47df-aee8-ed177237afed.png?v=1630342879"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
