INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('BIOMASK.S SOIN DE BARBE 50ML','Biomask.s','Cheveux','huile précieuse « BIOMASK.S » est le fruit de plusieurs années de recherche dans l’aromathérapie. Son mélange de 12 huiles essentielles et végétales d’une 1ère pression à froid lui procure des actions sur le follicule pileux, permettant de stopper la chute toute en favorisant sa repousse au niveau du visage, cheveux et thorax.',13110,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/biomask.png?v=1630342888',10,1,'6728763474095','39909635522735','https://beautymarket.ma/products/biomask-s-soin-de-barbe-50ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/biomask.png?v=1630342888"]','0') ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Bionnex whitexpert creme eclaircissante 30ml','Bionnex','Visage','La crème de soin pour la peau Whitexpert Stain, avec ses essences naturelles, favorise l’équilibre et la brillance du teint. Avec sa formule développée spécialement pour les peaux tachées, il aide à prévenir la régénération de la production de mélanine, qui provoque des taches cutanées.

Enrichit la peau avec une formule enrichie en vitamine C et aide à éliminer les taches

utilisation:

Il est appliqué deux fois par jour le matin et le soir après le nettoyage de la peau. Il est appliqué sur le visage et le cou en massant doucement sans le contour des yeux. La crème solaire est recommandée pour une utilisation avec la série preventiva',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/bionnex-perfederm-creme-eclaircissante-30ml_16cc9ebb-7de6-421f-afce-36767631fa55.jpg?v=1630342926',10,1,'6728765079727','39909638373551','https://beautymarket.ma/products/bionnex-whitexpert-creme-eclaircissante-30ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/bionnex-perfederm-creme-eclaircissante-30ml_16cc9ebb-7de6-421f-afce-36767631fa55.jpg?v=1630342926"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
