INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Centaurea Creme Depigmentante HQ 50ml','Centaurea','Visage','La Crème dépigmentante de centaurea est un soin quotidien qui permet une prise en charge efficace des tâches pigmentaires. Elle agit de façon rapide et visible sur les tâches brunes. Le teint s’éclaircit et devient homogène.',28500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Centaurea-Creme-depigmentente_5e7d8e63-d884-4199-883e-29ef99ce8d69.png?v=1630343219',10,1,'6728781201583','39909670748335','https://beautymarket.ma/products/centaurea-creme-depimentante-hq-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Centaurea-Creme-depigmentente_5e7d8e63-d884-4199-883e-29ef99ce8d69.png?v=1630343219"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Centaurea Creme Cicatrisante Spf30 50ml','Centaurea','Solaires','La Crème Réparatrice Centaurea est un soin de référence pour la peau qui allie des propriétés réparatrices et antibactériennes. La crème cicatrisante Centaurea permet, à la fois de réparer, d’assainir, et d’apaiser les épidermes irrités des adultes comme des enfants et des nourrissons.

Sans Parfum, sans paraben.

Caractéristiques

Réparatrice : Le Sucralfate, actif original et réparateur, rétablit rapidement le confort cutané en favorisant la régénération de l’épiderme.

Antibactérienne : L’association sulfate de cuivre, sulfate de zinc et oxyde de zinc à des concentrations synergiques, permet de lutter efficacement contre le développement excessif de germes.

Conseils d’utilisation

Nettoyer et sécher préalablement la peau.

Appliquer la crème réparatrice Centaurea 1 à 2 fois par jour.

Indications

Centaurea Crème cicatrisante réparatrice est particulièrement indiquée pour soigner les irritations sèches des adultes, enfants et nourrissons. Elle peut être appliquée sur la peau comme sur les muqueuses.

Pour toute question sur une indication en particulier, veuillez consulter au préalable votre médecin.',9900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/centaurea-creme-cicatrisante_70f5a1c4-73d2-45ae-a114-5bdd34eb9962.png?v=1630343221',10,1,'6728781332655','39909671010479','https://beautymarket.ma/products/centaurea-creme-cicatrisante-spf30-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/centaurea-creme-cicatrisante_70f5a1c4-73d2-45ae-a114-5bdd34eb9962.png?v=1630343221"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Centaurea Lait Corporel Hydratant 24H 500ml','Centaurea','Visage','Lait corporel hydratant 24H, formulé pour les peaux déshydratées, il ressource intensément la peau lui permettant de retrouver élasticité, douceur et aspect satine des l’application.

Enrichi en extrait de fleur de coton, complexe hydro-essentiel et agents filmogènes, il hydrate durablement, compense le dessèchement cutané et reconstitue la barrière protectrice de surface.',18000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/CentaureaLait-corporel_0b362d62-e1ad-4667-9623-895182ee5a63.png?v=1630343223',10,1,'6728781430959','39909671141551','https://beautymarket.ma/products/centaurea-lait-corporel-hydratant-24h-500ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/CentaureaLait-corporel_0b362d62-e1ad-4667-9623-895182ee5a63.png?v=1630343223"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Centaurea Gel Moussant Purifiant Anti Acne 200ml','Centaurea','Visage','Le gel nettoyant anti-acné CENTAUREA est un traitement local de l’acné.

Il associe une action antibactérienne a une action kératolytique et sébostatique, et lutte ainsi contre l’inflammation de la peau, son épaississement et la production excessive de sébum qui entretient l’acné.

Le gel nettoyant anti-acné CENTAUREA procure un nettoyage efficace et assure une peau nette, sa formule pénètre en profondeur dans les pores pour éliminer les impuretés, l’excès des cellules mortes à la surface de la peau pour un teint net et d’apparence saine.',13900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/centaureaGel-Anti-acne-200ml_e4fd9710-5b44-48e0-a401-fd2ce9721ebc.png?v=1630343225',10,1,'6728781562031','39909671272623','https://beautymarket.ma/products/centaurea-gel-moussant-purifiant-anti-acne-200ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/centaureaGel-Anti-acne-200ml_e4fd9710-5b44-48e0-a401-fd2ce9721ebc.png?v=1630343225"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CENTAUREA GEL NETTOYANT SURGRAS 200ML','Centaurea','Bébé & Maman','Liquide moussant doux préserve et hydrate la peau du visage et du corps

