INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cetaphil Oily Skin Cleanser – Nettoyant peaux grasses 236 ml','Cetaphil','Visage','Gel nettoyant peu moussant à la niacinamide (B3) et au panthénol (B5) qui nettoie en profondeur et réduit l’apparence des pores, sans dessécher. Peaux mixtes à grasses et sensibles. Gamme Cetaphil Sensitive Skin – Nettoyants, laboratoire Galderma.

Les bienfaits

Élimine impuretés, excès de sébum et maquillage

Réduit l’apparence des pores

Ne dessèche pas et ne tiraille pas

Niacinamide (B3) et panthénol (B5) pour la barrière cutanée

Testé par des dermatologues, doux pour les peaux sensibles

Sans savon, non comédogène, non irritant

pH doux (5,5–6,1)

Compatible avec les traitements anti-acné

Pour adolescents et adultes

Mode d’emploi

Nettoyer la peau matin et soir, puis rincer. Appliquer ensuite un soin hydratant sur la peau encore humide.

Précautions

Usage externe. Éviter le contact avec les yeux.

Ingrédients

Aqua, Glycerin, Cocamidopropyl Betaine, Disodium Laureth Sulfosuccinate, Sodium Cocoamphoacetate, Panthenol, Niacinamide, Pantolactone, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Sodium Benzoate, Parfum, Amyl Cinnamal, Citronellol, Geraniol, Hydroxycitronellal, Linalool, Sodium Chloride, Citric Acid.',12000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1q8-vmeGzTXJBbJM3RQZ8vprmwTnkUwNL_s0.png?v=1793462802',10,1,'6728785723567','39909678252207','https://beautymarket.ma/products/cetaphil-oily-skin-cleanser-png-236ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1q8-vmeGzTXJBbJM3RQZ8vprmwTnkUwNL_s0.png?v=1793462802"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
