INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMACEUTIC FOAMER 5 MOUSSE EXFOLIANTE DOUCE 100ML','Dermaceutic','Visage','Foamer 5 est un peeling doux sous forme de mousse. Cette mousse nettoyante élimine les impuretés et les cellules mortes tout en purifiant la peau en douceur. L''Acide glycolique dosé à 5% exfolie la peau en profondeur et rend le film hydrolipidique imperméable. Elle contient également de l''Enoxolone: apaisante et calmante, elle prévient l''inflammation de la peau.

Idéale pour le teint terne avec un grain de peau irrégulier à imperfections.

Conseils d''utilisation

Appliquer une noix de mousse sur le visage préalablement humidifié, masser puis rincer à l''eau après 2 minutes ou dès les premiers picotements.',27500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dermaceutic-foamer-5-100ml__06-1.webp?v=1792250699',10,1,'6728816459951','39909740708015','https://beautymarket.ma/products/dermaceutic-foamer-5-nettoyant-expert-doux-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/dermaceutic-foamer-5-100ml__06-1.webp?v=1792250699"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
