INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Dermalift sunlift BB Crème 50ml','DermaLift','Maquillage','Protection quotidienne de la peau contre les rayons UVB et UVA pour tous types de peaux. Elle hydrate, camoufle, protège, soigne et booste l’éclat de la peau.

