INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('KERACNYL GLYCOLIC+ Crème désincrustante 30ml','Ducray','Visage','Crème désincrustanteAffine le grain de peau - Réduit l''excès de sébum - Lisse - Désincruste les pores

