INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DUCRAY MELASCREEN UV FLUID ANTI TACHESLÉGER PEAUX NORMALES À MIXTES SPF50+ 50 ML','Ducray','Solaires','Le fluide protecteur SPF50+ antitaches MELASCREEN prévient et réduit l’apparence des taches brunes, tout en protégeant la peau au quotidien.
Il possède une double efficacité sur les taches et sur le vieillissement cutané :
- L’ACIDE AZELAÏQUE reconnu pour réduire les taches brunes installées, délivre une action antioxydante.
- Le filtre solaire breveté TRIASORB™ à la très haute protection SPF50+ ultra large spectre, protège la peau des méfaits des rayonnement UVB/UVA courts et longs et de la lumière bleue.
Sa texture fluide, non grasse et non collante allie hydratation et fini invisible, sur la majorité des carnations. Excellente base de maquillage, il résiste à l’eau et à la sueur et convient parfaitement à une utilisation quotidienne sur les peaux normales à mixtes.
Tolérance optimale qui convient aux femmes enceintes ou allaitantes. Non comédogène et développé pour minimiser les risques allergiques.

Bénéfices

• PRÉVIENT l’apparition de nouvelles taches brunes
• ÉCLAIRCIT les taches brunes brunes pour 100% des sujets*
• PROTÈGE contre les UVB, UVA courts et longs, la lumière bleue et la pollution',19900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ducray-melascreen-fluide-anti-taches-protectrice-spf50-50ml.webp?v=1761152904',10,1,'6728843493551','39909804900527','https://beautymarket.ma/products/ducray-melascreen-uv-creme-legere-spf50-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ducray-melascreen-fluide-anti-taches-protectrice-spf50-50ml.webp?v=1761152904"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
