INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Ducray Melascreen Concentré antitaches 30 ml','Ducray','Visage','A la pointe de l’innovation, le concentré antitaches MELASCREEN est la 1ère solution dermatologique spécialement développée pour dépigmenter efficacement tous les types de taches brunes installées* grâce à une très haute concentration en actifs dermatologiques dépigmentants (15%). Ils agissent directement à 3 différents niveaux sur les 3 facteurs responsables de leur formation :
Niveau 1 : L’HESPERIDINE METHYLCHALCONE™ réduit la taille des vaisseaux sanguins superficiels.
Niveau 2 : L’ACIDE AZELAÏQUE régule la surproduction de la mélanine à la source grâce à une action sélective.
Niveau 3 : L’ACIDE GLYCOLIQUE favorise l''élimination des cellules mortes en surface pour réduire l''intensité des taches brunes.
Parfaitement adapté pour offrir une dépigmentation sélective même sur les taches brunes les plus difficiles à corriger, ce concentré antitaches préserve la pigmentation naturelle de la peau. Le teint est plus uniforme et homogène à partir de seulement 2 semaines d’utilisation**.
Un soin ciblé sans parfum à la texture légère, au fini non gras et non collant doté d’une bonne tolérance adaptée à tous les types de peau.
Convient aux femmes enceintes et allaitantes. Non comédogène et développé pour minimiser les risques allergiques.',25900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2_641c5d6a-f859-4f7f-99a1-17916f4fbfef.webp?v=1761153012',10,1,'6728846213295','39909810962607','https://beautymarket.ma/products/ducray-melascreen-depigmentant-soin-d-attaque-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/2_641c5d6a-f859-4f7f-99a1-17916f4fbfef.webp?v=1761153012"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
