INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Brosse à dents kids ice age 2-6 years','Elgydium','Hygiène','ELGYDIUM KIDS L’ÂGE DE GLACE 2-6 ans est une brosse à dents spécialement conçue pour les petites mâchoires grâce à sa petite tête. Ses brins souples et finement arrondis respectent les dents et la gencive. La coupe de l’extrémité des brins est concave pour s’adapter à la surface bombée des dents de lait. Les brins colorés de la taille d’un petit pois indiquent la bonne dose de dentifrice à appliquer. Son design L’ÂGE DE GLACE motive à se brosser les dents régulièrement.',4800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056018190_57186264-1ac0-4881-965f-ba8918981c62.jpg?v=1630344374',10,1,'6728853356719','39909829443759','https://beautymarket.ma/products/elgy-bad-kids-ice-age-2-6-years',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056018190_57186264-1ac0-4881-965f-ba8918981c62.jpg?v=1630344374"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
