INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Pocket – Brosse à dents Medium','Elgydium','Hygiène','ELGYDIUM POCKET est une brosse à dents de voyage. La technicité Elgydium à emporter partout : vacances, bureau… Des brins courts pour l’émail et des brins longs pour les espaces interdentaires et le massage des gencives.',3515,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056007347_e15c5bb3-9a4b-4005-a422-d16b598318a8.jpg?v=1630344406',10,1,'6728855191727','39909834260655','https://beautymarket.ma/products/elgydium-pocket-brosse-a-dents-medium',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056007347_e15c5bb3-9a4b-4005-a422-d16b598318a8.jpg?v=1630344406"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Kids Monster – Brosse à dents 2-6 Ans','Elgydium','Hygiène','ELGYDIUM KIDS MONSTER 2-6 ans est une brosse à dents qui possède une petite tête spécialement conçue pour les petites mâchoires. Ses brins souples et finement arrondis ont été développés pour respecter les dents et la gencive. La coupe de l’extrémité des brins est concave pour s’adapter à la surface bombée des dents de lait.',4800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056008085_60edb77a-98c7-46ac-b407-61d2ec1d13eb.jpg?v=1630344408',10,1,'6728855290031','39909834391727','https://beautymarket.ma/products/elgydium-kids-monster-brosse-a-dents-2-6-ans',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056008085_60edb77a-98c7-46ac-b407-61d2ec1d13eb.jpg?v=1630344408"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Clinic – Brosse à dents Ortho X Adulte Medium','Elgydium','Hygiène','La brosse ELGYDIUM CLINIC ORTHODONTIE Adultes s’adresse aux adultes porteurs d’appareils orthodontiques. Sa technologie brevetée d’implantation des brins en X permet d’offrir un brossage optimal : les brins externes croisés nettoyent les zones difficiles d’accès et les brins centraux assurent le brossage des bagues.',3230,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056009532_c18e7432-a22a-472c-9bbf-4d69a9d95adc.jpg?v=1630344410',10,1,'6728855421103','39909834817711','https://beautymarket.ma/products/elgydium-clinic-brosse-a-dents-ortho-x-adulte-medium',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056009532_c18e7432-a22a-472c-9bbf-4d69a9d95adc.jpg?v=1630344410"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Kids – Dentifrice Banane 2-6 Ans – 50 ml','Elgydium','Hygiène','ELGYDIUM KIDS Banane est un dentifrice destiné aux enfants de 2 à 6 ans. Aromatisé à la banane, il apporte une dose de 500 ppm de fluor, adaptée, chez les enfants de cet âge, à la protection des dents de lait contre les attaques acides responsables de caries.',4500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056009976_3ac66f15-5c90-4714-ae22-ef66faedb696.jpg?v=1630344412',10,1,'6728855584943','39909835079855','https://beautymarket.ma/products/elgydium-kids-dentifrice-banane-2-6-ans-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056009976_3ac66f15-5c90-4714-ae22-ef66faedb696.jpg?v=1630344412"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
