INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Junior – Dentifrice Bubble Gum 7-12 Ans','Elgydium','Hygiène','ELGYDIUM JUNIOR Bubble Gum 7-12 ans est un dentifrice destiné aux enfants de 7 à 12 ans. Aromatisé au bubble gum, il apporte une dose de 1 000 ppm de fluor, adaptée, chez les enfants de cet âge, à la protection des premières dents définitives contre les attaques acides responsables de caries.',4500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056010033_a19f0707-c9c2-4132-b213-a269a63ee61b.jpg?v=1630344416',10,1,'6728855879855','39909836357807','https://beautymarket.ma/products/elgydium-junior-dentifrice-bubble-gum-7-12-ans',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056010033_a19f0707-c9c2-4132-b213-a269a63ee61b.jpg?v=1630344416"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium – Dentifrice Dents sensibles – 75 ml','Elgydium','Hygiène','ELGYDIUM DENTS SENSIBLES est un gel dentifrice peu abrasif qui apporte une dose de fluor adaptée à une protection efficace des dents sensibles (1250 ppm d’ions fluor). Il contribue à diminuer l’hypersensibilité dentinaire lors de l’ingestion d’aliments chauds ou froids, acides ou sucrés.',5000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056012280_77bdbb6f-46b1-4a30-b5cf-a2b8370aba49.jpg?v=1630344418',10,1,'6728856043695','39909836652719','https://beautymarket.ma/products/elgydium-dentifrice-dents-sensibles-75-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056012280_77bdbb6f-46b1-4a30-b5cf-a2b8370aba49.jpg?v=1630344418"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Dentifrice Blancheur 75 ml','Elgydium','Hygiène','ELGYDIUM BLANCHEUR est un dentifrice qui contribue à éliminer les taches dentaires superficielles (dues notamment à l’alimentation ou au tabac) tout en respectant les dents. Aromatisé à la menthe, il prolonge la blancheur obtenue après un détartrage ou un éclaircissement professionnel.',4700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/esresresr.png?v=1763981875',10,1,'6728856174767','39909837045935','https://beautymarket.ma/products/elgydium-dentifrice-blancheur-75-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/esresresr.png?v=1763981875"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
