INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elgydium Junior – Brosse à dents l’Âge de Glace 7-12 Ans','Elgydium','Hygiène','ELGYDIUM JUNIOR L’ÂGE DE GLACE 7-12 ans est idéale pour les premières dents définitives. Ses brins arrondis respectent les dents et les gencives des enfants. Sa coupe festonnée facilite le nettoyage des zones interdentaires. Son design L’ÂGE DE GLACE motive à se brosser les dents régulièrement.',4800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056018206_820fb3ee-50c0-4d2f-8184-c22b685df52a.jpg?v=1630344433',10,1,'6728856830127','39909838094511','https://beautymarket.ma/products/elgydium-junior-brosse-a-dents-l-age-de-glace-7-12-ans',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3577056018206_820fb3ee-50c0-4d2f-8184-c22b685df52a.jpg?v=1630344433"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
