INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Elliance Emulsion Cicatrisante','Elliance','Corps','L’émulsion favorise la réparation tissulaire grâce à l’action conjuguée des principes actifs spécialement sélectionnés.

1.Action anti-inflammatoire (Allantoïne bisabolol, dipotassium glycyrrhizate)

2.Action antiseptique (huile essentielle, extrait d’aloe vera)

3.Action simulatrice de la reconstruction tissulaire (silicium organique)

4.Action réparatrice (vitamine B5, tripeptide 2, silicium organique).

INDICATIONS :

.Eraflures

.Brûlures

.Cicatrices déjà formées

.Fissures anales

.Cicatrisation hémorroïdaire

.Suite d’interventions chirurgicales, dermatologiques et gynécologiques

POSOLOGIE :

Une application matin et soir',10800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/9244-thickbox_default_7515a4e7-bedd-4b11-bf2f-5e3f486cb4f9.jpg?v=1630344474',10,1,'6728858697903','39909843140783','https://beautymarket.ma/products/elliance-emulsion-cicatrisante',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/9244-thickbox_default_7515a4e7-bedd-4b11-bf2f-5e3f486cb4f9.jpg?v=1630344474"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
