INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Eric favre Gelee Royale & miel Kids 10Ampoules*10ml','Eric Favre','Bien-être','Ces ampoules à boire avec une paille (fournies avec le produit) sont idéales pour les enfants de plus de 2 ans et va les aider à renforcer leur défenses naturelles et leur immunité.

