INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Excipial U 10 Lipolotion 200ml','Excipial','Corps','- Traitement des xéroses

- En association aux traitements de la dermatite atopique et du psoriasis

- Utilisation quotidienne, seule ou en association avec des traitements médicamenteux

- Soin régénérateur de la peau sèche

