INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('FILORGA GLOBAL REPAIR ESSENCE 150ml','Filorga','Visage','Cette lotion visage enrichie en NCEF nourrit la peau et agit intensément sur tous les signes du vieillissement cutané : déshydratation, rides marquées, manque de fermeté du visage, ovale relâché, manque d’homogénéité et teint fatigué.

