INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('ISDIN Fotoprotecteur Fusion fluide mineral 50Ml','Isdin','Solaires','ISDIN | FOTOPROTECTOR ISDIN® FUSION FLUID MINERAL SPF 50+ 50 ML
