INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Hairstim Cheveux & Ongles 60 Gelules','Hairstim','Cheveux','Les bienfaits de hairstimm cheveux et ongles sont dus à l’action senergique de ses composants ( levure de bièren Algue marine, ortie, pollen & sésame) qui contribuent à apporter un supplément en nutriments essentiels aux cheveux & ongles pour renforcer leur structure, et leur donner plus d’éclat et de vigueur.

