INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Herôme Sérum de Croissance Pour Ongles – 7 ml','Herôme','Maquillage','Description
Idéal pour stimuler la croissance de vos ongles, le sérum Herôme est enrichi en acide aminés et en silicium extrait de l’ortie blanche.
