INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Institut Esthederm – Esthe-White System Mousse Nettoyante Éclaircissante Jeunesse – 150 ml','Institut Esthederm','Visage','Pour insuffler un nouvel éclat à votre peau, cette mousse nettoyante assure un nettoyage éclaircissant tout en légèreté. Sa formulation en parfaite affinité avec la peau concilie préservation du capital jeunesse et homogénéité du teint. Un pur délice qui révèle jour après jour une peau plus nette, plus lumineuse.',31200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020012690_1ab1f7d3-fdd6-40a7-826a-2fe8e45c7555.jpg?v=1630345576',10,1,'6728911618223','39909950554287','https://beautymarket.ma/products/institut-esthederm-esthe-white-system-mousse-nettoyante-eclaircissante-jeunesse-150-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020012690_1ab1f7d3-fdd6-40a7-826a-2fe8e45c7555.jpg?v=1630345576"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Institut Esthederm – Esthe-White System Soin Jour Hydratant Éclaircissant Jeunesse – 50 ml','Institut Esthederm','Visage','Le SOIN JOUR HYDRATANT ÉCLAIRCISSANT JEUNESSE clarifie le teint, prévient les hyperpigmentations et prévient les dommages causés par les agressions environnementales. Estompe immédiatement les imperfections et sublime le teint.',47405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020012942_f49c2263-d824-4b21-8443-e8b68dce73c6.jpg?v=1630345578',10,1,'6728911683759','39909950685359','https://beautymarket.ma/products/institut-esthederm-esthe-white-system-soin-jour-hydratant-eclaircissant-jeunesse-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020012942_f49c2263-d824-4b21-8443-e8b68dce73c6.jpg?v=1630345578"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
