INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Institut Esthederm – Intensive Hyaluronic Sérum – 30 ml','Institut Esthederm','Visage','Molécule naturellement présente dans la peau, l’acide hyaluronique est un réservoir d’eau naturel, garant de la jeunesse et de la fermeté cutanées. Le sérum Intensive Hyaluronic® est un sérum acide hyaluronique qui associe trois formes différentes d’acide hyaluronique pour hydrater intensément et stimuler la production d’acide hyaluronique naturel.',51200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020014014_eb05f092-8ed8-417f-8af1-7f76632f1735.jpg?v=1630345584',10,1,'6728911880367','39909951865007','https://beautymarket.ma/products/institut-esthederm-intensive-hyaluronic-serum-30-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3461020014014_eb05f092-8ed8-417f-8af1-7f76632f1735.jpg?v=1630345584"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
