INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('KIN DENTIFRICE BLANCHEUR 75 ML','Kin','Hygiène','Les soins bucco-dentaires sont de plus en plus importants, tant sur le plan de l’hygiène que sur celui de l’esthétique. Une bouche saine n’est pas seulement une manifestation de santé et de jeunesse évidente, mais elle affecte également nos relations sociales. C’est pourquoi l’intérêt pour l’amélioration des techniques de blanchiment des dents et l’utilisation de produits de blanchiment des dents a considérablement augmenté.',5800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/kin-dentifrice-blancheur-75ml-hygiene_c84ad624-afbb-4360-b86c-7112a80d974a.webp?v=1784739936',10,1,'6728923218095','39909988630703','https://beautymarket.ma/products/kin-dentifrice-blancheur-75-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/kin-dentifrice-blancheur-75ml-hygiene_c84ad624-afbb-4360-b86c-7112a80d974a.webp?v=1784739936"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
