INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME DE JOUR DÉFENSE LUMIÈRE DU DIAMANT50ml','Lancior','Solaires','La CRÈME DÉFENSE LUMIÈRE DU DIAMANT va protéger la peau contre les méfaits des UVA-UVB et réveiller un teint plus radieux et plus clair. Sa formule, à base de vraie poudre de Diamant extra-fine, va aider à révéler une peau plus jeune et plus lumineuse.

INGRÉDIENTS ACTIFS :

CYTOBIOLTM IRIS A2: issu de la synergie de trois éléments actifs, il contient du zinc, un dérivé de vitamine A et un extrait d’Iris florentina. Il va aider à cibler les imperfections pour révèler une peau lumineuse et éclatante. POUDRE DE DIAMANT: va uniformiser la peau, affiner l’épiderme et illuminer le teint pour un éclat exceptionnel de jeunesse.

CONSEILS D’UTILISATION :

Appliquer le matin sur visage et cou parfaitement propres.',66405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Lighting-Defense-Cream-Ref.-F21618HD_0e11ec86-fdf4-4646-bac9-0890d4b2c73f.jpg?v=1630346335',10,1,'6728940978351','39910056624303','https://beautymarket.ma/products/lancior-creme-de-jour-defense-lumiere-du-diamant50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Lighting-Defense-Cream-Ref.-F21618HD_0e11ec86-fdf4-4646-bac9-0890d4b2c73f.jpg?v=1630346335"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME DES YEUX LUMIÈRE DU DIAMANT 20ML','Lancior','Visage','La CRÈME DES YEUX LUMIÈRE DU DIAMANT contient des actifs puissants ciblés pour le contour des yeux. Pour rendre lumière et souplesse à la peau, pour retrouver un regard éclatant de jeunesse.

INGRÉDIENTS ACTIFS

POLYLIFT ® : protéine d’amande douce qui aide à restaurer l’élasticité de la peau grâce à ses effets hydratants, adoucissants et nourrissants. BEAUTIFEYE : dérivé de l’arbre de soie persan Albizia Julibrissin, ce puissant ingrédient actif va apporter un effet liftant au contour des yeux. Il aide à lutter contre les poches et les cernes pour rendre aux yeux un regard rafraîchi et rajeuni.

CONSEILS D’UTILISATION

Appliquer matin et soir sur le contour de l’œil et tapoter délicatement du bout des doigts de l’intérieur vers l’extérieur.',47405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Lighting-Eye-Cream-Ref.-F21818HD_0687892c-4842-4a4a-ac72-1fbb6edbb492.jpg?v=1630346337',10,1,'6728941109423','39910056951983','https://beautymarket.ma/products/lancior-creme-des-yeux-lumiere-du-diamant-20ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Lighting-Eye-Cream-Ref.-F21818HD_0687892c-4842-4a4a-ac72-1fbb6edbb492.jpg?v=1630346337"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME DETOX ÉCLAT DE PERLE NUIT 50ML','Lancior','Visage','La CRÈME DÉTOX ÉCLAT DE PERLE – NUIT aide à défendre et à protéger la peau contre la pollution. Sa formule douce hydrate et nourrit, le teint retrouve ainsi fraîcheur et éclat.

INGRÉDIENTS ACTIFS

GINSENG: pour une action énergisante et une puissante protection de l’épiderme. COTON: aide à bloquer les radicaux libres responsables du vieillissement prématuré de la peau. Il défend efficacement des métaux lourds et gaz nocifs.

CONSEILS D’UTILISATION

Appliquer le soir sur visage et cou parfaitement propres.',66405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Pearl-Radiance-Detox-Night-Cream-Ref.-20218HD-1_a7019725-cb1f-4c3b-a8cb-050aceea68a7.jpg?v=1630346339',10,1,'6728941174959','39910057148591','https://beautymarket.ma/products/lancior-creme-detox-eclat-de-perle-nuit-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Pearl-Radiance-Detox-Night-Cream-Ref.-20218HD-1_a7019725-cb1f-4c3b-a8cb-050aceea68a7.jpg?v=1630346339"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME LIFT YEUX OR INTEMPOREL 20ML','Lancior','Visage','La CRÈME LIFT YEUX OR INTEMPOREL contient des actifs puissants ciblés pour le contour des yeux, pour agir efficacement contre les effets du temps (rides, poches, cernes). Ils vont aider à rendre lumière et souplesse à la peau, pour retrouver un regard éclatant de jeunesse.

INGRÉDIENTS ACTIFS

POLYLIFT ® : protéine d’amande douce qui aide à restaurer l’élasticité de la peau grâce à ses effets hydratants, adoucissants et nourrissants. POUDRE D’OR : vertus antioxydantes et protectrices, l’Or apporte un effet lifting immédiat. ARGIRELINE ® : apporte un effet «Botox-like» graçe à son action sur tous les signes du vieillissement cutané.

CONSEILS D’UTILISATION

Appliquer matin et soir sur le contour de l’œil et tapoter délicatement du bout des doigts de l’intérieur vers l’extérieur.',47405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/LANCIOR-OR-CONTOUR-YEUX_3090c48b-3fe4-4d1c-9458-77e02bcb83f4.jpg?v=1630346341',10,1,'6728941273263','39910057476271','https://beautymarket.ma/products/lancior-creme-lift-yeux-or-intemporel-20ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/LANCIOR-OR-CONTOUR-YEUX_3090c48b-3fe4-4d1c-9458-77e02bcb83f4.jpg?v=1630346341"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME PRÉCIEUSE JEUNESSE LIFT JOUR OR 50ml','Lancior','Solaires','La CRÈME PRÉCIEUSE JEUNESSE – LIFT JOUR va aider à lutter éfficacement contre les rides du temps (âge, déshydratation, expression), accélèrer leur réparation et lifter délicatement le visage. La peau retrouve son élasticité et les contours sont remodelés.

INGRÉDIENTS ACTIFS

LIFTISS ® SB TENSEUR : obtenu à partir de la pulpe des fruits qui enrobent les graines du Baobab. Lifte et lisse la peau du visage, pour réduire visiblement les signes de l’âge. POUDRE D’OR : vertus antioxydantes et protectrices, l’Or apporte un effet lifting immédiat.

CONSEILS D’UTILISATION

Appliquer le matin sur visage et cou parfaitement propres.',66405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Youth-Precious-Cream-Day-Lift-Ref.-F20518HD_3367566b-17c5-4281-9583-96b7ef3bd592.jpg?v=1630346342',10,1,'6728941404335','39910057902255','https://beautymarket.ma/products/lancior-creme-precieuse-jeunesse-lift-jour-or-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Youth-Precious-Cream-Day-Lift-Ref.-F20518HD_3367566b-17c5-4281-9583-96b7ef3bd592.jpg?v=1630346342"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR CRÈME PROTECT ÉCLAT DE PERLE JOUR 50ML','Lancior','Solaires','La CRÈME PROTECT ÉCLAT DE PERLE – JOUR va renforcer la barrière cutanée et protéger la peau des agressions climatiques. Ses actifs hydratants agissent en douceur, le teint retrouve ainsi fraîcheur et éclat.

INGRÉDIENTS ACTIFS

CIRE DE CARNAUBA: permet de renforcer la fonction barrière de la peau et de lutter contre les effets néfastes de la pollution et du climat (vent et froid). HUILE DE MORINGA: aide à restaurer l’élasticité de la peau grâce à son effet hydratant et nourrissant.

CONSEILS D’UTILISATION

Appliquer le matin sur visage et cou parfaitement propres.',66405,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Pearl-Radiance-Detox-Night-Cream-Ref.-20218HD_54965df2-aedb-4577-ba0d-bd4f9fe2dcc6.jpg?v=1630346344',10,1,'6728941502639','39910058328239','https://beautymarket.ma/products/lancior-creme-protect-eclat-de-perle-jour-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Pearl-Radiance-Detox-Night-Cream-Ref.-20218HD_54965df2-aedb-4577-ba0d-bd4f9fe2dcc6.jpg?v=1630346344"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LANCIOR GOMMAGE LUMIÈRE POUDRE DE DIAMANT 50ML','Lancior','Visage','Le GOMMAGE LUMIÈRE POUDRE DE DIAMANT va éliminer les cellules mortes, l’excès de sébum, les impuretés et les toxines. Sa formule à base de vraie poudre de Diamant extra-fine va purifier la peau en douceur et révéler un teint lumineux. À utiliser avec le Masque Lumière Poudre de Diamant, pour un rituel éclaircissant parfait.

INGRÉDIENTS ACTIFS :

HUILE ESSENTIELLE DE MENTHE: grâce à ses propriétés anti- bactériennes, il va nettoyer la peau en profondeur pour un teint parfaitement frais et plus radieux. POUDRE DE DIAMANT: va uniformiser la peau, affiner l’épiderme et illuminer le teint pour un éclat exceptionnel de jeunesse.

CONSEILS D’UTILISATION :

Appliquer sur visage humide, masser délicatement par mouvements circulaires et rincer à l’eau tiède.',56905,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Powder-Illuminating-Scrub-Ref.-F21918HD_e72c13ba-6315-4e2f-91ca-a265c57d2b2e.jpg?v=1630346346',10,1,'6728941600943','39910058459311','https://beautymarket.ma/products/lancior-gommage-lumiere-poudre-de-diamant-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Diamond-Powder-Illuminating-Scrub-Ref.-F21918HD_e72c13ba-6315-4e2f-91ca-a265c57d2b2e.jpg?v=1630346346"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
