INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Lca Pharma Crème Dépigmentante 40Ml','LCA Pharma','Visage','La Crème dépigmentante est un soin quotidien qui permet une prise en charge efficace des tâches pigmentaires. Elle agit de façon rapide et visible sur les tâches brunes. Le teint s’éclaircit et devient homogène.

PRINCIPAUX ACTIFS :

Acide ascorbique : freine la synthèse de la mélanine, anti-oxydantAcide lactique : stimule le renouvellement cellulaire, favorise l’élimination de la pigmentation existanteAcide kojique : freine la synthèse de la mélanine

CONSEILS D’UTILISATION :

Appliquer matin et soir sur les zones concernées en massant légèrement.

La crème dépigmentante peut s’utiliser en association avec le masque dépigmentant.',31400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/creme-depigmentante-lcapharma_997d8781-f738-485f-b00c-4f14b0f0232a.jpg?v=1630346381',10,1,'6728943272111','39910062751919','https://beautymarket.ma/products/lca-pharma-creme-depigmentante-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/creme-depigmentante-lcapharma_997d8781-f738-485f-b00c-4f14b0f0232a.jpg?v=1630346381"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('LCA PHARMA Crème réparatrice 120ml','LCA Pharma','Corps','La crème réparatrice a été formulée pour apaiser les rougeurs et les irritations superficielles de l’épiderme, telles que les coups de soleil et les échauffements cutanés liés aux frottements.

La crème réparatrice stimule la reconstruction de la barrière cutanée en favorisant le renouvellement cellulaire. Grâce à son effet filmogène, la peau est durablement hydratée et protégée.

PRINCIPAUX ACTIFS :

- Huile d’avocat : hydratant, restructurant, apaisant

- Panthénol : hydratant, cicatrisant, apaisant

- Hydroxyproline : hydratant, raffermissant, restructurant

- Squalane végétal : hydratant, réparateur

- Beurre de karité : hydratant, réparateur, protecteur, cicatrisant, apaisant

CONSEILS D’UTILISATION :

Appliquer 1 à 2 fois par jour en couche épaisse sur la zone concernée en faisant pénétrer par de légers massages.',14600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LCAE.jpg?v=1793095613',10,1,'6728943370415','39910062882991','https://beautymarket.ma/products/lca-pharma-creme-reparatrice-120ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LCAE.jpg?v=1793095613"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
