INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Maelys Shampooing Anti-Chute Ortie Prêle – 200 ml','Maelys','Cheveux','Conseils d’utilisation

