INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Magiclear Savon Clarifiant Exfoliant','Magiclear','Visage','Le Savon Clarifiant Exfoliant est pour le corps ce que le Nettoyant Action Double est pour le visage.

Elimine les cellules mortes,

Nettoie la peau en profondeur,

Stimule la régénération cellulaire de cellules saines et plus claires,

Neutralise les odeurs corporelles provoquées par les bactéries et microbes à la surface de la peau,

Agit contre la déshydratation de la peau.

Contient de la glycérine, de la poudre d’abricot et un parfum correcteur d’odeurs.

Conseils d’utilsation:

Utiliser matin et soir, suivre avec la Lotion Corporelle Clarifiante.',11400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRERERSE.png?v=1706612330',10,1,'6728951857327','39910101385391','https://beautymarket.ma/products/magiclear-savon-clarifiant-exfoliant',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/SRERERSE.png?v=1706612330"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Magiclear Nettoyant Action Double 100ML','Magiclear','Visage','Nettoyant Action Double est un gel 2 en 1 nettoyant et exfoliant.

