INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Mam Baby Attache-sucette Clip+Cover +0m','Mam Baby','Bébé & Maman','Stable et polyvalente comme jamais, la nouvelle attache MAM Clip peut être utilisée avec les différents types de sucettes et avec les autres accessoires pour bébé.

