INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('meridol Brosse à dents PROTECTION GENCIVES souple','Meridol','Hygiène','La brosse à dents meridol® PROTECTION GENCIVES souple se distingue par ses brins coniques aux extrémités microfines comme un pinceau, qui éliminent les restes alimentaires et la plaque de la surface des dents jusqu’aux sillons gingivaux. Le nettoyage des dents et du rebord gingival se fait ainsi en profondeur et en douceur, ménageant les gencives même irritées.',3700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-14.jpg?v=1630346805',10,1,'6728962113711','39910136479919','https://beautymarket.ma/products/meridol-brosse-a-dents-protection-gencives-souple',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-14.jpg?v=1630346805"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('meridol Bain de bouche PROTECTION GENCIVES 400ml','Meridol','Hygiène','Le bain de bouche meridol® PROTECTION GENCIVES combat la cause de l’irritation des gencives: les bactéries situées sur le rebord gingival. Soin quotidien des dents et des gencives, le bain de bouche apaisant fonctionne efficacement, pour garder les dents et les gencives propres et saines.

