INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('MIRADENT MIRAWHITE GELEE BLANCHISSANTE 100 ml','Miradent','Hygiène','Mirawhite gelee est une gelée blanchissante et lissante qui contient des micro particules issues de la nano technologie qui rendent les dents nettement plus lisses.Ces micro particules remplissent les micro-fissures de la surface des dents.

