INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NaturEsoin Huile d’Arbre a Thé – 50 ml','NaturEsoin','Cheveux','Huile pour les peaux et les cheveux. – Antiseptique puissant et assainissant cutané. – Utilisée dans les traitements d’appoint des affections de la peau en cas d’acné, du érythème fessier du bébé et de la croûte de lait. – Apaise les piqûres d’insectes et les coups de soleil. – Utilisée en massage dans plusieurs cas de problèmes de la peau. – Soulage les démangeaisons du cuir chevelu.',4200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/6111259370654_0a4dc2ab-5636-416e-889e-5ce2769eab60.jpg?v=1630347268',10,1,'6728982069423','39910174097583','https://beautymarket.ma/products/naturesoin-huile-d-arbre-a-the-50-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/6111259370654_0a4dc2ab-5636-416e-889e-5ce2769eab60.jpg?v=1630347268"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
