INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NaturEsoin Huile de Noix de Coco – 100 ml','NaturEsoin','Cheveux','Huile extraite de l’albumen fraîche de la noix de coco et utilisée pour les soins du visage, du corps et des cheveux. Huile hydratante, assouplissante, nourrissante et fortifiante. Prévient les vergetures et atténue efficacement leur apparition. Hydrate, assouplit les zones sèches et sensibles de la peau et les débarrasse des impuretés et des cellules mortes. Nourrit et hydrate le cuir chevelu, fortifie les cheveux et préserve leur brillance et combat les pellicules.',3500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/6111259373426_e83eb3bf-660f-4e47-a75c-38402392f8f9.jpg?v=1630347273',10,1,'6728982331567','39910174523567','https://beautymarket.ma/products/naturesoin-huile-de-noix-de-coco-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/6111259373426_e83eb3bf-660f-4e47-a75c-38402392f8f9.jpg?v=1630347273"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
