INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA NORESUN GRADUAL UV CRÈME TEINTÉE SPF 50+ 40ml','Noreva','Solaires','Noresun® Gradual UV est la nouvelle génération de soins solaires « intelligents » capables d’adapter

