INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA EXFOLIAC ACNOMÉGA 200 SOIN CORRECTEUR INTENSIF 30ml','Noreva','Visage','Soin kérato-actif des peaux à imperfections modérées à sévères pour une action renforcée

