INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA ZENIAC  LP SOIN KERATOREGULATEUR  30 ml','Noreva','Visage','Soin quotidien des peaux fines et grasses, Zeniac® LP Soin kératorégulateur exfolie et affine le grain de peau.

