INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA EXFOLIAC GEL MOUSSANT INTENSIF 200 ml','Noreva','Visage','Spécialement élaboré pour nettoyer les peaux jeunes à imperfections,

Exfoliac® Gel moussant intensif favorise l’élimination des impuretés,

