INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA EXFOLIAC BB CRÈME CLAIRE 30 ml','Noreva','Visage','Spécialement formulé pour corriger et masquer les imperfections,

