INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NOREVA AQUAREVA CRÈME HYDRATANTE 24H LÉGÈRE 40ml','Noreva','Visage','Spécifiquement formulée pour les peaux déshydratées normales à mixtes,

Aquareva® Crème hydratante légère ressource et hydrate la peau en profondeur en procurant un confort immédiat et durable.

