INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Novexpert Vitamine C Flash Eclat Mousse Nettoyante – 150 ml','Novexpert','Visage','Description

