INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('NUHANCIAM FLUIDE PHOTO PROTECTeur SPF50+ 50ml','Nuhanciam','Solaires','Ce soin est indispensable en cas d’exposition à la lumière solaire. La texture légère et non grasse ne laisse qu’un toucher velouté, doux, mat. Elle a été conçue pour permettre le maquillage. Ce soin est indispensable en cas d’exposition à la lumière solaire.

