INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('O’LYSEE Solution hydro-alcoolique pour l’antisepsie des mains 200ml','O''lysée','Autres soins','Une SOLUTION HYDRO-ALCOOLIQUE développée pour l’antisepsie des mains suite à l’arrêté du 13 mars 2020 autorisant par dérogation la mise à disposition sur le marché et l’utilisation temporaire de certains produits hydro-alcooliques utilisés en tant que biocides désinfectants pour l’hygiène humaine.

Ce spray ne contient pas de gaz propulseur, la formule active est contenue dans une valve à poche sous pression d’air comprimé.

Cette solution hydro-alcoolique est composée de 74% d’alcool et d’une petite quantité de peroxyde d’hydrogène reconnus respectivement pour leurs propriétés désinfectantes et sporicides.',3705,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/OLYSEE_34f40ffd-99dd-4908-8d8a-f75eb149fed4.jpg?v=1630347834',10,1,'6729004515503','39910212731055','https://beautymarket.ma/products/o-lysee-solution-hydro-alcoolique-pour-l-antisepsie-des-mains-200ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/OLYSEE_34f40ffd-99dd-4908-8d8a-f75eb149fed4.jpg?v=1630347834"]','-1') ON CONFLICT(source_variant_id) DO NOTHING;
