INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('OMRON TENSIOMETRE BRASSARD M3 CONFORT','Omron','Bien-être','- Tensiomètre Electronique au Bras Omron M3 Comfort

