INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Onagrine ona-hydratant creme riche 40ml','Onagrine','Visage','Cette crème généreuse et gourmande, apaise, restaure l’épiderme et renforce les mécanismes d’hydratation de la peau.

