INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Onagrine Visibly Pure Gelee Nett Gommante 200ml','Onagrine','Visage','La gelée Gommante Onagrine Paris permet de libérer la peau de ses toxines et la purifie.

