INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Photo White Correcteur Face Fluide N°12','Photo White','Maquillage','Produit multifonctionnel qui combine en une seule application l’action hydratante et protectrice d’une crème de jour et le pouvoir colorant d’un fond de teint. Grâce à son pouvoir couvrant élevé, il unifie le teint et masque efficacement les imperfections sans l’alourdir. Convient pour un maquillage simple et quotidien en un seul geste. Contient un dépigmentant cutané pour lutter contre la décoloration et un facteur de protection solaire pour lutter contre le photo-vieillissement. Sans parfum.',13300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-7-1.jpg?v=1630348087',10,1,'6729016279215','39910233047215','https://beautymarket.ma/products/photo-white-correcteur-face-fluide-n-12',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-7-1.jpg?v=1630348087"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Photo White Serum Anti-Taches 15ml','Photo White','Cheveux','Sérum à base d’acide mandélique avec une action exfoliante douce, convient également aux peaux les plus sensibles. Il favorise un renouvellement superficiel de l’épiderme (plus terne et épaissi chez les peaux matures), neutralise les taches cutanées et rend la peau du visage plus douce et plus lumineuse.',23600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/photo-white-serum-anti-tache-depigmentant-15ml_1_1.jpg?v=1736877595',10,1,'6729016311983','39910233079983','https://beautymarket.ma/products/photo-white-serum-anti-taches-15ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/photo-white-serum-anti-tache-depigmentant-15ml_1_1.jpg?v=1736877595"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Photo White AH Sérum Acide Hyaluronique 30ml','Photo White','Visage','Sérum concentré à base d’acide hyaluronique à haut et bas poids moléculaire pour une action hydratante intense et un effet anti-âge contre les signes du temps. Le traitement procure au visage une sensation immédiate de fraîcheur et de tonicité, la peau retrouve ainsi son élasticité et sa souplesse.il contient un mélange d’actifs végétaux qui contrent le processus de mélanogénèse pour donner un effet éclaircissant sur le visage.',37900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-8_160a8336-0a93-432e-aafe-46bd65b8cea1.jpg?v=1630348093',10,1,'6729016574127','39910233604271','https://beautymarket.ma/products/photo-white-ah-creme-acide-hyaluronique-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/New-Project-8_160a8336-0a93-432e-aafe-46bd65b8cea1.jpg?v=1630348093"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
