INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PUR BIBERON A MÉDICAMENT OU SUCETTE À REMPLIR 6505','Pur','Bébé & Maman','- 10cc. / 2 cuillères à café.
