INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('PUR BIBERON EN VERRE 250ML','Pur','Bébé & Maman','- Conception ergonomique. Conçu pour fournir une prise facile, pendant l’alimentation.

