INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE COMPHREE 40ML','Racine Vita','Visage','– chauffe relaxe et calme les muscles.

– tonifie et assouplie la peau.

– huile de massage.

– prépare le muscle avant l’effort physique.

– fait disparaître les ampoules.

