INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE CANNELLE 40ML','Racine Vita','Visage','– Désinfectante et désodorisante.

– Favorise la cicatrisation des boutons noires et des acnés.

– Tonifiante, stimulante et combat les verrues.

– Action anti cellulite et amincissante par échauffement.

– Utile en massage de corps.

– Antibactérienne très puissante à large spectre d’action buccales cutanées.',3500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-de-cannelle-40-ml_06db3fa4-022e-40c0-88dc-b3ecf1229ad9.jpg?v=1630348679',10,1,'6729037414575','39910282920111','https://beautymarket.ma/products/racine-vita-huile-cannelle-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-de-cannelle-40-ml_06db3fa4-022e-40c0-88dc-b3ecf1229ad9.jpg?v=1630348679"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE DE JOJOBA 40ML','Racine Vita','Cheveux','– Éclaircit les tâches de rousseur et de vieillisse.

– Tonique, dépurative et amincissante.

– Adoucit et tonifie l’épiderme.

– Supprime les points noirs du visage et resserre les pores.

– Renforce les ongles cassants.

