INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE ESSENTIELLE DE CITRON 10 ML','Racine Vita','Bien-être','L’essence de Citron est réputée pour ses vertus : fortifiante,antiseptique,cicatrisante,reminéralisante,tonique et amincissante. Elle est idéale en diffusion avec ses notes amères et acidulées pour purifier l’air ambiant et repousser les odeurs désagréables. favorise la cicatrisation de la peau,apaise les démangeaisons et prévient les rides. Elle est connue aussi pour faciliter la concentration et la redynamise.',4100,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-de-citron-10-ml_0afac3a3-886a-47a3-a775-d6b78a4db18c.jpg?v=1630348734',10,1,'6729040036015','39910293995695','https://beautymarket.ma/products/racine-vita-huile-essentielle-de-citron-10-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-de-citron-10-ml_0afac3a3-886a-47a3-a775-d6b78a4db18c.jpg?v=1630348734"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA 7 HUILES CAPILLAIRES 125ML','Racine Vita','Cheveux','L’huile Capillaire Racine-Vita revitalise et stimule la repousse les cheveux. C’est un soin intensif, nourrissant et restructurant pour tous types de cheveux . Cette huile est également adaptée en cas de cuir chevelu irrité, pour les cheveux permanentés et colorés, ou abîmés par le sèche-cheveux ou le soleil. Sa composition à base des huiles de germe de blé, d’huile d’argan et l’huile d’avocat, etc.…. combat les pellicules, renforce les cheveux et les rend plus souples et facile à coiffer. L’huile Capillaire donne aux cheveux une nouvelle vitalité.( Anti-chute, Anti-pelliculaire).',3800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-7-huiles-capillaires-125ml_7d1e1bba-b427-4e9a-ad77-1f893f197fa6.jpg?v=1630348736',10,1,'6729040101551','39910294257839','https://beautymarket.ma/products/racine-vita-7-huiles-capillaires-125ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-7-huiles-capillaires-125ml_7d1e1bba-b427-4e9a-ad77-1f893f197fa6.jpg?v=1630348736"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
