INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE D’EUCALYPTUS 40ML','Racine Vita','Bien-être','L’huile d’eucalyptus est très utile en hiver. Elle est indiquée pour soigner les bronchites, sinusites, grippes, et rhumes. C’est aussi une huile qui stimule les défenses immunitaires du corps. Elle vous protègera contre les épidémies de l’hiver.',3300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-eucalyptus-40-ml_d9d30c6c-6cd4-4c2d-9fa8-c3772573d13b.jpg?v=1630348739',10,1,'6729040265391','39910294651055','https://beautymarket.ma/products/racine-vita-huile-d-eucalyptus-40ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-eucalyptus-40-ml_d9d30c6c-6cd4-4c2d-9fa8-c3772573d13b.jpg?v=1630348739"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Racine vita huile de ricin 40 ml','Racine Vita','Cheveux','L’huile de ricin est une substance très riche qui pénètre rapidement. Elle contribue à atténuer l’apparence des taches brunes sur la peau.Utilisé pour assouplir les cheveux épais ou crépus.

L’huile de ricin est Parfaite pour les cheveux secs, dévitalisés, aux pointes fourchues ou très cassants.

Elle favorise la croissance des cils et des sourcils.',1700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-de-ricin-40ml_e70a89b0-d489-42f5-8650-eee3b38b38d5.jpg?v=1630348741',10,1,'6729040363695','39910294913199','https://beautymarket.ma/products/racine-vita-ricin-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-de-ricin-40ml_e70a89b0-d489-42f5-8650-eee3b38b38d5.jpg?v=1630348741"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
