INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE ESSENTIELLE D’EUCALYPTUS 10 ML','Racine Vita','Bien-être','L’huile essentielle d’Eucalyptus Radiata est l’une des rares huiles essentielles à pouvoir être utilisée par tous (sauf les femmes enceintes de – de 3 mois qui ne peuvent pas utiliser les huiles essentielles). Majoritairement composée de 1,8-cinéole, molécule qui possède une activité expectorante et mucolytique puissante, elle est très efficace pour tous les problèmes ORL comme le rhume, la sinusite, l’angine, la bronchite ou tout simplement la toux.',3800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-d-eucalyptus-10-ml_6dea331b-cab4-4ed1-91da-c4fabdc1f576.jpg?v=1630348748',10,1,'6729040527535','39910295371951','https://beautymarket.ma/products/racine-vita-huile-essentielle-d-eucalyptus-10-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-d-eucalyptus-10-ml_6dea331b-cab4-4ed1-91da-c4fabdc1f576.jpg?v=1630348748"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('RACINE VITA HUILE ESSENTIELLE GIROFLE 10 ML','Racine Vita','Bien-être','L’huile essentielle de clou de girofle est essentiellement composée d’eugénol : une molécule aux effets naturellement antiseptique, immunostimulant, anesthésiant et cicatrisant que l’on retrouve dans nombre de produits prescrits ou utilisés par les dentistes (bains de bouche, dentifrices spécialisés, pâte employée en chirurgie dentaire pour faire des pansements,…).

L’huile essentielle de clou de girofle peut être utilisée pour guérir ou calmer acné, bleus, coupures, brûlures, des plaies.

Elle agit comme un analgésique pour le rhumatisme et l’arthrite.

On dit aussi qu’elle est bonne pour le système digestif, attenuant vomissements, diarrhée, flatulence, spasmes et des parasites.

L’huile essentielle de clou de girogle est également connue pour soulager des problèmes respiratoires comme la bronchite, l’asthme et la tuberculose.

Dans l’aromathérapie, cette huile essentielle stimule l’esprit) et agit comme un aphrodisiaque. Il enlève l’épuisement mental et la fatigue et incite au sommeil en cas d’insomnies.',4200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-de-girofle-10-ml_27b49c1e-dee0-4c9e-ac60-1f9b209c4ffe.jpg?v=1630348749',10,1,'6729040625839','39910295634095','https://beautymarket.ma/products/racine-vita-huile-essentielle-girofle-10-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/racine-vita-huile-essentielle-de-girofle-10-ml_27b49c1e-dee0-4c9e-ac60-1f9b209c4ffe.jpg?v=1630348749"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
