INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('sanogyl dent soin gencive 75ml','Sanogyl','Hygiène','10% à 20% des adultes Français ont les gencives sensibles ou douloureuses.

Inflammation

Saignement

Risque de déchaussement

Pour mieux protéger votre capital gencive, Sanogyl a conçu le Soin Gencives.

Apaise

Protège

Soulage

Le Protectiv’SYSTEM de SANOGYL

Depuis 1923, Sanogyl a construit son expertise sur le soin des gencives et des dents. Les recherches du Laboratoire Sanogyl ont permis de développer le Protectiv’SYSTEM, un complexe unique alliant des agents antibactériens, un agent apaisant et du Fluor pour une protection complète des gencives et des dents.

En plus de cette protection, chaque dentifrice de la gamme Sanogyl vous offre un soin spécifique répondant à vos besoins.',3990,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Sanogyl-Dentifrice-Soin-Gencives-oma5y8q18s346480twl4qp4trf6z3ssl14yzkgia3k_3b02c99c-c44e-4be7-9fe7-85bd027522b3.jpg?v=1630349046',10,1,'6729052225711','39910330892463','https://beautymarket.ma/products/sanogyl-dent-soin-gencive-75ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Sanogyl-Dentifrice-Soin-Gencives-oma5y8q18s346480twl4qp4trf6z3ssl14yzkgia3k_3b02c99c-c44e-4be7-9fe7-85bd027522b3.jpg?v=1630349046"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
