INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Sensilis Supreme Night Cream 50ml','Sensilis','Visage','Le traitement Supreme Night est une crème à l’extrait de caviar et Longlife-Cell qui intensifie les fonctions cellulaires nocturnes renforçant la longévité cellulaire et régénérant votre peau en profondeur.

CONSEILS D’UTILISATION :

