INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Somatoline HOMME TRAITEMENT VENTRE ET ABDOMEN 10 NUITS 150ML','Somatoline','Corps','le Traitement Ventre et Abdomen Intensif Nuit 10 Somatoline COSMETIC est un soin minceur pour homme.

