INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Somatoline TRAITEMENT PREMIERE CELLULITE 150ML','Somatoline','Bien-être','On distingue plusieurs types de cellulite, en fonction de leurs caractéristiques. Dans ses premiers signes, la cellulite est dite “aqueuse”, et se manifeste principalement par une stagnation des liquides ainsi que par un ralentissement de la microcirculation sous cutanée, accompagnés d’un épaississement du tissu adipeux. Pour ce type de cellulite, il est conseillé d’utiliser une crème anti-cellulite à action drainante.

De la recherche et de l’innovation Somatoline Cosmetic est né Première Cellulite – Action Drainante, spécifiquement formulé pour combattre les premiers signes de la cellulite.',45220,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3596490003630-1_143410e3-e393-4362-9994-cd7342a55e66.jpg?v=1630349334',10,1,'6729065037999','39910359466159','https://beautymarket.ma/products/somatoline-traitement-premiere-cellulite-150ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/3596490003630-1_143410e3-e393-4362-9994-cd7342a55e66.jpg?v=1630349334"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
