INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Somatoline 7 NUITS ULTRA INTENSIF GEL FRAIS 400ML','Somatoline','Bien-être','Sa formule exclusive à l’action rapide, grâce au BioGelSlim7-complexTM hautement concentré en ingrédients actifs spécifiques, tel que le sel marin et la séricoside, permet d’obtenir des résultats visibles et cliniquement prouvés en seulement 7 nuits.

