INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Somatoline TRAITEMENT VENTRE ET HANCHES EXPRESS 150ML','Somatoline','Bien-être','Une texture, légère, qui pénètre rapidement après un léger massage, sans graisser la peau.

