INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SPECIAL KID SIROP VITAMINES FER 125ML','Special Kid','Bien-être','La gamme SPECIAL KID répond spécifiquement aux petits désagréments rencontrés par nos enfants au quotidien.

