INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Svr Densitium Contour Des Yeux 15ml','SVR','Visage','C’est un soin anti-âge complet du contour de l’œil : il lutte efficacement contre les rides, les cernes et les poches et agit sur le relâchement des paupières.

