INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR SUN SECURE Lait SPF50+ 100ML','SVR','Solaires','Pour toutes les peaux sensibles. Dès la naissance (hors prématurés). Visage et corps.

