INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Compresse Sterile 30*30 Cm Boite de 10','Urgo','Bien-être','Compresses de gaze pour le nettoyage des plaies nécessitant une détersion efficace: plaies aigues, souillées, chroniques.Elles peuvent être utilisées également en recouvrement sur des plaies exsudatives ou en recouvrement secondaire pour absorber les exsudats et protéger la plaie.Leur propriété hydrophile en fait un produit asséchant efficace.',1700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-compresses-steriles-20x20cm-boite-de-10_dd8d1d4f-dbe2-4430-aa4e-d7780a18aa0d.jpg?v=1630349694',10,1,'6729082568879','39910397444271','https://beautymarket.ma/products/urgo-compresse-sterile-30-30-cm-boite-de-10',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-compresses-steriles-20x20cm-boite-de-10_dd8d1d4f-dbe2-4430-aa4e-d7780a18aa0d.jpg?v=1630349694"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
