INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO ULTRA PROTECTEUR PANSEMENT PROTECTEUR Boite de 20','Urgo','Bien-être','efficacement des chocs. Micro-aéré, il laisse respirer la plaie.

Astuce !

Anti-adhérente, sa compresse ne colle pas à la plaie.

Mode d’emploi :

1. Nettoyer, désinfecter, rincer et sécher soigneusement la plaie et son pourtour.

2. Appliquer le pansement en lissant soigneusement les bords.

3. Renouveler le pansement au moins 2 fois par jour.',3325,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/URGO-ULTRA-PROTECTEUR_c251dcf3-a262-404f-85dc-136fc4663fb4.jpg?v=1630349697',10,1,'6729082798255','39910398066863','https://beautymarket.ma/products/urgo-ultra-protecteur-pansement-protecteur-boite-de-20',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/URGO-ULTRA-PROTECTEUR_c251dcf3-a262-404f-85dc-136fc4663fb4.jpg?v=1630349697"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Pansements Waterproof Assortis Boite de 20','Urgo','Bien-être','Film transparent extrêmement souple, adhésif des 4 côtés, Aquafilm est particulièrement adapté pour les usages en milieu humide (mer, piscine, bain, douche…).

Indications :

Film transparent extrêmement souple, adhésif des 4 côtés, Aquafilm est particulièrement adapté pour les usages en milieu humide (mer, piscine, bain, douche…).

Mode d’utilisation / Qualités

Renouveler au moins 2 fois par jour.

Grâce à son support innovant, Aquafilm est imperméable à l’eau et aux bactéries, ce qui assure une protection optimale de la plaie, et perméable à l’air, pour laisser la peau et la plaie respirer.',2600,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Urgo-Aqua-Protect-Pansements-3-Formats-20u_1.jpg?v=1752508819',10,1,'6729082896559','39910398132399','https://beautymarket.ma/products/urgo-pansements-waterproof-assortis-boite-de-20',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/Urgo-Aqua-Protect-Pansements-3-Formats-20u_1.jpg?v=1752508819"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
