INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Traitement Ampoules Doigt et Orteil Seconde Peau 6 Pansements','Urgo','Bien-être','Frottements répétés, pressions douloureuses, les doigts et les orteils sont très sollicités et sujets aux ampoules, en particulier lors de la pratique d’une activité sportive.

Le pansement Urgo Traitement Ampoules Doigt et Orteil agit comme une véritable seconde peau :

– Dès son application, il soulage la douleur.

– Au contact de l’humidité de l’ampoule, il forme un gel de protection dermo-reconstituant, qui isole la plaie des pressions et frottements et favorise la cicatrisation.

CONSEIL D’UTILISATION :

Si l’ampoule est percée, nettoyez à l’eau et au savon, et appliquez un antiseptique.

Ôtez le papier protecteur marqué Urgo et réchauffez votre pansement quelques instants dans la paume de votre main.

Décollez délicatement votre pansement de son support plastique en évitant de mettre vos doigts sur la partie adhésive.

Appliquez le pansement directement sur l’ampoule.

Lissez soigneusement les bords pour optimiser son adhésivité.

Indication : Traitement des ampoules des doigts et des orteils.',6460,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-pans-trait-amp-doigt-bte6_31fe9356-1357-42aa-ad45-5f95cfd1783a.jpg?v=1630349703',10,1,'6729083060399','39910398263471','https://beautymarket.ma/products/urgo-traitement-ampoules-doigt-et-orteil-seconde-peau-6-pansements',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-pans-trait-amp-doigt-bte6_31fe9356-1357-42aa-ad45-5f95cfd1783a.jpg?v=1630349703"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO PROTECTION OIGNONS HALLUX VALGUS','Urgo','Bien-être','Grâce à sa forme spécifique et son design étudié, URGO Protection Oignons garantit confort et stabilité tout en protégeant efficacement des pressions et des frottements douloureux des chaussures. Souple et réversible, il offre également une adaptabilité précieuse qui lui permet d’être utilisé sur le pied droit comme sur le pied gauche, peu importe la taille*. Lavable et réutilisable, le chausson Oignons s’oublie dans la chaussure pour une protection optimale.

Conseils d’utilisation :

1. Enfiler la protection sur le pied en veillant à positionner le coussinet en gel polymère sur la zone douloureuse à protéger.

2. Si besoin, nettoyer la protection à l’eau savonneuse, rincer et laisser sécher. Egalement lavable en machine à 30°C. Ce produit convient pour le pied gauche et le pied droit.

Précautions d’emploi :

- Ne pas utiliser plus de 16h par jour

- Ne pas utiliser sur une plaie ouverte ou suintante

- Consultez un médecin avant utilisation en cas de diabète ou en cas de problème de circulation sanguine

- Ne pas appliquer plus de 30 jours consécutifs

- Ne pas laisser à la portée des enfants',11400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/PROTECTION-OIGNON-HALLUX-VALGUS_ccfc86e9-6be2-4a74-8c07-89b8319427b2.png?v=1630349705',10,1,'6729083191471','39910398558383','https://beautymarket.ma/products/urgo-protection-oignons-hallux-valgus',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/PROTECTION-OIGNON-HALLUX-VALGUS_ccfc86e9-6be2-4a74-8c07-89b8319427b2.png?v=1630349705"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO FILMOGEL STOP ONGLES RONGES 9ML','Urgo','Bien-être','Grâce à sa formule innovante, urgo stop aux ongles rongés combine 2 actions :

– Empêche de se ronger les ongles.

– Renforce et restructure.

– Invisible

CONSEILS D’UTILISATION :

Lire attentivement la notice à l’intérieur de la boite.',9500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/filmogel-stop-ongles-ronges-9ml-urgo_c45d8576-2f61-450e-9a53-8c03d1357b8e.jpg?v=1630349708',10,1,'6729083388079','39910398722223','https://beautymarket.ma/products/urgo-filmogel-stop-ongles-ronges-9ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/filmogel-stop-ongles-ronges-9ml-urgo_c45d8576-2f61-450e-9a53-8c03d1357b8e.jpg?v=1630349708"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Gel Arnica 50G','Urgo','Bien-être','Grâce à sa texture gel légère, URGO Arnica Gel pénètre facilement la peau.

Mode d’emploi :

Appliquer le gel sur la zone concernée, par des massages légers. Renouveler l’application 2 à 3 fois par jour. Se laver les mains après utilisation.

Précautions d’emploi :

- Ne pas appliquer sur une plaie ouverte, sur une coupure, sur les muqueuses ou à proximité des yeux.

- Ne pas laisser à la portée des enfants.

- Peut être utilisé chez l’enfant à partir de 1 an.

- Ne pas utiliser sur des personnes sensibles à l’arnica.

- Réservé à l’usage externe.

- Ne pas avaler.',3800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/urgo-urgo-arnica-gel-tube-50-g-sante_1.jpg?v=1741268927',10,1,'6729083519151','39910398886063','https://beautymarket.ma/products/urgo-gel-arnica-50g',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/urgo-urgo-arnica-gel-tube-50-g-sante_1.jpg?v=1741268927"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Bande De Gaze 3*10Cm','Urgo','Bien-être','Idéal pour la fixation des pansement et le maintien léger des articulations.',350,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-bande-a-gaz-3mx10cm_30bbced6-c0d7-4cab-9b0f-c140a8ac8c33.jpg?v=1630349712',10,1,'6729083617455','39910398951599','https://beautymarket.ma/products/urgo-bande-de-gaze-3-10cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-bande-a-gaz-3mx10cm_30bbced6-c0d7-4cab-9b0f-c140a8ac8c33.jpg?v=1630349712"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
