INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Bande De Gaze 3*7Cm','Urgo','Bien-être','Idéal pour la fixation des pansement et le maintien léger des articulations.',300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-bande-de-gaze-hydrophile-3mx7cm_2bc00480-b157-4ba2-96b4-0ce3f90c0e08.jpg?v=1630349718',10,1,'6729084043439','39910400393391','https://beautymarket.ma/products/urgo-bande-de-gaze-3-7cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-bande-de-gaze-hydrophile-3mx7cm_2bc00480-b157-4ba2-96b4-0ce3f90c0e08.jpg?v=1630349718"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Strapping 2.5M*8Cm','Urgo','Bien-être','La bande de strapping de la marque Urgo est idéale suite à un traumatisme, une entorse, un claquage ou pour le maintien des zones fragilisées. Urgo strapping maintient les articulations qui en ont besoin pour vous permettre de reprendre vos activités. Il s’adapte parfaitement aux mouvements et laisse respirer la peau.

Urgo strapping est sans latex et sa texture très élastique légèrement adhésive lui permet de se poser très facilement sur la zone fragilisée et d’être réajustée à tout moment. Cette bande adhésive s’adapte parfaitement aux contours anatomiques.

Composition : Bande élastique tissée enduite d’une masse adhésive élastomèrique sans solvant.',6460,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-douleurs-strapping_f6c5cf5d-56a0-4560-933a-c8ad4ecbd96e.jpg?v=1630349720',10,1,'6729084141743','39910400458927','https://beautymarket.ma/products/urgo-strapping-2-5m-8cm',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-douleurs-strapping_f6c5cf5d-56a0-4560-933a-c8ad4ecbd96e.jpg?v=1630349720"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Strapping 2.5M*10Cm','Urgo','Bien-être','La bande de strapping de la marque Urgo est idéale suite à un traumatisme, une entorse, un claquage ou pour le maintien des zones fragilisées. Urgo strapping maintient les articulations qui en ont besoin pour vous permettre de reprendre vos activités. Il s’adapte parfaitement aux mouvements et laisse respirer la peau.

Urgo strapping est sans latex et sa texture très élastique légèrement adhésive lui permet de se poser très facilement sur la zone fragilisée et d’être réajustée à tout moment. Cette bande adhésive s’adapte parfaitement aux contours anatomiques.

Composition : Bande élastique tissée enduite d’une masse adhésive élastomèrique sans solvant.',8170,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-douleurs-strapping.jpg?v=1630349724',10,1,'6729084207279','39910400524463','https://beautymarket.ma/products/urgo-strapping-2-5m-10cm',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-douleurs-strapping.jpg?v=1630349724"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Resistant 1M*6 Cm','Urgo','Bien-être','La bande Urgo est à découper au format désiré pour la protection des petites plaies du quotidien. Son support est textile, il résiste à toutes les situations.

La compresse contient un antiseptique, il assure ainsi la protection microbienne des plaies superficielles, et ne collent pas à la plaie grâce à la gaze anti-adhérente qui la protège.',2700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-resistant-bande_67027898-3bac-4717-b8ce-734062e3bc51.jpg?v=1630349725',10,1,'6729084305583','39910400589999','https://beautymarket.ma/products/urgo-resistant-1m-6-cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-resistant-bande_67027898-3bac-4717-b8ce-734062e3bc51.jpg?v=1630349725"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Clean 10cm*10cm','Urgo','Bien-être','Le pansement UrgoClean se présente sous la forme d’une compresse stérile, non tissée, composée de fibres hydro-détersives (polyacrylate) à haut niveau d’absorption et de cohésion. Cette innovation unique consiste à croiser par thermoliaison, dans un plan parallèle à la plaie, des fibres de polyacrylate selon une disposition structurale qui confère à UrgoClean ses propriétés d’absorption et de piégeage des résidus fibrineux de la plaie et de résistance à la traction. Cette compresse hydro-détersive est enduite par une matrice lipido-colloïde micro-adhérente (TLC-contact) qui se gélifie facilitant ainsi le drainage des résidus fibrineux, le positionnement et le retrait du produit. Au contact des exsudats, les particules lipidocolloïdes issues de la TLC-contact se gélifient créant un milieu humide favorable à la détersion. Concomitamment, les fibres hydro-détersives de polyacrylate se gélifient et se fixent aux résidus fibrineux, les absorbent et les drainent afin d’en faciliter l’élimination. En conséquence, la fixation et le drainage des résidus fibrineux par la structure hydro-détersive UrgoClean associée à sa TLC-Contact favorisent la phase de détersion des plaies fibrineuses.',3900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgoclean_3b020386-beef-44f0-97a1-bf0d8d493881.jpg?v=1630349729',10,1,'6729084436655','39910400753839','https://beautymarket.ma/products/urgo-clean-10cm-10cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgoclean_3b020386-beef-44f0-97a1-bf0d8d493881.jpg?v=1630349729"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO FILMOGEL APHTE ET PETITES PLAIES BUCCALES 6ML','Urgo','Bien-être','Le produit URGO Aphtes et petites plaies buccales est indiqué dans le traitement des aphtoses mineures exclusivement (1 à 2 aphtes par crise d’un diamètre <1 cm) ainsi que des petites plaies de la muqueuse buccale.',6800,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/FILMOGEL_a21cbb74-e05b-4570-8a26-9d43cf4ee51c.jpg?v=1630349731',10,1,'6729084567727','39910400852143','https://beautymarket.ma/products/urgo-filmogel-aphte-et-petites-plaies-buccales-6ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/FILMOGEL_a21cbb74-e05b-4570-8a26-9d43cf4ee51c.jpg?v=1630349731"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO SANYRÈNE 10 ML','Urgo','Bien-être','Le Sanyrène est une solution pour le traitement préventif des escarres et protéger les zones cutanées qui y sont sujettes.

LE SANYRÈNE URGO POUR LE TRAITEMENT PRÉVENTIF DES ESCARRES

Le Sanyrène permet le maintien du niveau d’oxygénation tissulaire, restaure la fonction barrière de l’épiderme et reconstitue le film hydrolipique épidermique.

CARACTÉRISTIQUES DE LA SOLUTION PRÉVENTIVE

- Conseils d’utilisation : A appliquer 2 à 3 fois par jour sur une peau saine.

- Composition : Glycérides hyperoxygénés d’acides gras essentiels (linoleïque à 60 %), Tocophérol (vitamine E) : 99 %, Parfum anis : 1 %',7500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/105269-sanyrene-10ml_563a1678-3dbc-4617-87ba-039912afdb86.jpg?v=1630349733',10,1,'6729084633263','39910400917679','https://beautymarket.ma/products/urgo-sanyrene-10-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/105269-sanyrene-10ml_563a1678-3dbc-4617-87ba-039912afdb86.jpg?v=1630349733"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Plastic Sparadrap Plastique Transparent 2,5cmx5m','Urgo','Bien-être','Le sparadrap plastique transparent Urgo Plastic a été conçu dans le but de fixer un pansement ou une compresse. Hypoallergénique, il a pour particularité de jouir d’une très bonne tolérance cutanée et convient parfaitement aux personnes ayant la peau sensible.

Ce sparadrap transparent Urgo Plastic est généralement indiqué en dermatologie afin de réaliser des pansements sur les peaux fragiles, mais aussi lors de chirurgie réparatrice ou de chirurgie facile pour mettre en place des pansements plus discrets. De plus, ce type de sparadrap peut également être utilisé en services d’urgences ou de réanimation afin de fixer des sondes ou des cathéters nécessitant une surveillance visuelle.

Imperméable à l’eau ainsi qu’aux bactéries, il permet à la peau de respirer correctement et épouse parfaitement les courbes anatomiques.',1425,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-pore_a55b42e8-d36c-4089-80e2-aac2ccc4652e.jpg?v=1630349735',10,1,'6729084731567','39910400983215','https://beautymarket.ma/products/urgo-plastic-sparadrap-plastique-transparent-2-5cmx5m',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-pore_a55b42e8-d36c-4089-80e2-aac2ccc4652e.jpg?v=1630349735"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO COMPRESSES STÉRILES DE GAZE 20cmX20cm','Urgo','Bien-être','Les compresses stériles de Gaze URGO ont une forte capacité d’absorption, sont hypoallergéniques et stériles pour une hygiène optimale.

conseils d’utilisation :

1. Ouvrir le sachet sans toucher la compresse pour qu’elle conserve sa caractéristique stérile.

2. Nettoyer la plaie à l’aide d’une compresse sèche ou imprégnée de sérum physiologique.

3. Si nécessaire, badigeonner la plaie avec une compresse imprégnée d’une solution antiseptique liquide ou d’un autre principe actif.',1200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-compresse-steriles-20X20_644a6627-ae72-4ae2-be19-d2a163ba2f2b.jpg?v=1630349737',10,1,'6729084797103','39910401015983','https://beautymarket.ma/products/urgo-compresses-steriles-de-gaze-20cmx20cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-compresse-steriles-20X20_644a6627-ae72-4ae2-be19-d2a163ba2f2b.jpg?v=1630349737"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO  Urgo Extensible Boite de 30','Urgo','Bien-être','Les pansements confort extensibles Urgo sont des pansements micro-aérés particulièrement recommandés pour les peaux sensibles qui s’adaptent parfaitement aux mouvements du corps. Ils sont composés d’une compresse qui ne colle pas à la plaie et qui renferme un antiseptique protégeant la plaie des infections microbiennes.

CONSEILS D’UTILISATION :

Nettoyer, désinfecter, rincer et sécher soigneusement la plaie et son pourtour.

Appliquer le pansement.

Renouveler le pansement au moins 2 fois par jour.',2090,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-extensible-bte-30_677bbd80-c35a-4535-8fa1-c130b6bf1f34.jpg?v=1630349739',10,1,'6729084895407','39910401114287','https://beautymarket.ma/products/urgo-urgo-extensible-boite-de-30',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-extensible-bte-30_677bbd80-c35a-4535-8fa1-c130b6bf1f34.jpg?v=1630349739"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO VERRUES','Urgo','Bien-être','Les verrues apparaissent sous plusieurs formes, principalement sur les pieds et les mains. Les verrues communes ou vulgaires sont habituellement rugueuses et dures et ont l’aspect d’un « chou-fleur ». Les verrues plantaires ont souvent des bords durs et épais avec des points noirs au centre. Disgracieuses et récidivantes, les verrues peuvent être gênantes, voire même douloureuses.

Conseils d’utilisation :

URGO Verrues, Traitement par cryothérapie est une méthode sûre, innovante et efficace pour éliminer à domicile les verrues des pieds et des mains. Son applicateur transparent et son embout spécifique permettent un positionnement précis sur la verrue pour la geler au cœur.

De plus, sa valve doseuse délivre la quantité adaptée de cryogène pour traiter les verrues quelques soient leurs tailles. Idéal pour les enfants, son action de courte durée et graduelle limite les sensations douloureuses.',15200,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/urgo-verrues-mains-et-pieds-traitement-par-cryotherapie-38-ml_1.jpg?v=1769245554',10,1,'6729084960943','39910401278127','https://beautymarket.ma/products/urgo-verrues',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/urgo-verrues-mains-et-pieds-traitement-par-cryotherapie-38-ml_1.jpg?v=1769245554"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Ampoules Talon Sport 5 Pansements','Urgo','Bien-être','Pansement hydrocolloïde dermo-reconstituant seconde peau pour le traitement de l’ampoule localisée sur le talon. Boîte de 5 pansements.

Utilisation:

1. Si l’ampoule est percée, nettoyez à l’eau et au savon, et appliquez un antiseptique.

2. Ôtez le papier protecteur marqué Urgo et réchauffez votre pansement dans la paume de votre main.

3. Décollez délicatement votre pansement de son support plastique en évitant de mettre vos doigts sur la partie adhésive.

4. Appliquez sur peau propre et sèche en positionnant la partie centrale du pansement directement sur l’ampoule.

5. Lissez soigneusement les bords pour optimiser son adhésivité.

Conseils :

Le pansement se décollera de lui-même au bout de 2 à 3 jours.

Ne jamais découper un pansement. Urgo Traitement Ampoules.

Ne pas réutiliser un même pansement.

Contre-indiqué en cas d’infection.',5985,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-ampoules-talons-sport-orange-5_39da26ff-164f-4d08-8289-a45eb293ad63.jpg?v=1630349743',10,1,'6729085059247','39910401343663','https://beautymarket.ma/products/urgo-ampoules-talon-sport-5-pansements',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgo-ampoules-talons-sport-orange-5_39da26ff-164f-4d08-8289-a45eb293ad63.jpg?v=1630349743"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Strips 100X12.5 Unitée','Urgo','Bien-être','Sutures cutanées des plaies superficielles et incisions médicales',950,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/fournier-urgostrips-10-steriles-face_1e521637-5607-4011-90e1-adf014cfcb64.jpg?v=1630349744',10,1,'6729085157551','39910401507503','https://beautymarket.ma/products/urgo-strips-100x12-5-unitee',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/fournier-urgostrips-10-steriles-face_1e521637-5607-4011-90e1-adf014cfcb64.jpg?v=1630349744"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO AMPOULES TRAITEMENT ULTRA DISCRET TALON FORMAT MOYEN','Urgo','Bien-être','URGO Ampoules Ultra discret – Talon isole l’ampoule des pressions et des frottements pour soulager immédiatement la douleur. Au contact de l’ampoule du pied, la technologie hydrocolloïde forme un gel dermo-reconstituant qui favorise la cicatrisation de l’ampoule du talon. Ultra discret et résistant, il est le pansement de référence pour traiter les ampoules tout en portant des chaussures ouvertes.

Mode d’emploi pour traiter l’ampoule :

1. Ne percez pas l’ampoule. Si l’ampoule est déjà percée, nettoyez à l’eau et au savon, et appliquez un antiseptique.

2. Enlevez l’ailette transparente (zone fléchée) et réchauffez votre pansement dans les paumes de vos mains avant d’enlever le papier protecteur décoré.

3. Appliquez sur peau propre et sèche en positionnant la partie centrale du pansement directement sur l’ampoule.

4. Lissez soigneusement les bords pour optimiser son adhésivité.

5. Le pansement se décollera de lui-même au bout de 2 à 3 jours. Il est conseillé d’attendre que le pansement se décolle spontanément.',5985,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Urgo-Ampoules-Discret_5a6ac30d-4716-47fa-99e5-f76c27f20dff.png?v=1630349746',10,1,'6729085288623','39910401638575','https://beautymarket.ma/products/urgo-ampoules-traitement-ultra-discret-talon-format-moyen',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Urgo-Ampoules-Discret_5a6ac30d-4716-47fa-99e5-f76c27f20dff.png?v=1630349746"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('URGO DOULEURS PLANTAIRES MÉTATARSIENNES','Urgo','Bien-être','URGO Douleurs Plantaires Métatarsiennes est un coussinet de protection contenant un gel polymère qui amortit les pressions et soulage la douleur. Lavable et réutilisable, ce coussinet, dont le design a été étudié pour une tenue optimale, reste en place dans la chaussure toute la journée en toute discrétion. L’allié idéal pour une sensation de confort et de liberté de mouvement retrouvée !

Mode d’emploi :

1. Enfiler un coussinet sur chaque pied en veillant à utiliser le coussinet adapté (une boite contient un coussinet pour le pied droit et un coussinet pour le pied gauche).

2. Si besoin, nettoyer les coussinets à l’eau savonneuse, rincer et laisser sécher.

3. Également lavable en machine à 30°C.

Précautions d’emploi :

- Ne pas utiliser plus de 16h par jour.

- Ne pas utiliser sur une plaie ouverte ou suintante.

- Consultez un médecin avant utilisation en cas de diabète ou en cas de problème de circulation sanguine.

- Ne pas appliquer plus de 30 jours consécutifs.

- Ne pas laisser à la portée des enfants.',20330,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/DOULEURS-PLANTAIRES_2298e904-d267-441b-b17b-8a243c9b53f1.png?v=1630349749',10,1,'6729085386927','39910401802415','https://beautymarket.ma/products/urgo-douleurs-plantaires-metatarsiennes',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/DOULEURS-PLANTAIRES_2298e904-d267-441b-b17b-8a243c9b53f1.png?v=1630349749"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Protection Cors 2 Digitubes à Découper','Urgo','Bien-être','Urgo Protection Cors 2 Digitubes à Découper est une protection discrète, confortable et pratique, idéale pour les cors des pieds.

Le tube en silicone protège efficacement des frottements et pressions. Transparent, il est aussi confortable et élastique, très facile à enfiler. Il est enduit d’une huile hydratante et assouplissante qui ramollit le cor.

Contient : 2 digitubes réutilisables de 8 cm à découper.

CONSEIL D’UTILISATION :

Couper la longueur désirée à l’aide d’une paire de ciseaux.

Enfiler sur l’orteil en recouvrant le cor à protéger.

Indication : Protéger les cors de pieds.',5890,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/2-digitubes-reutilisables-a-decouper-protection-cors_b8f36336-ca6a-47b8-88ab-8c432087cc42.jpg?v=1630349750',10,1,'6729085485231','39910401867951','https://beautymarket.ma/products/urgo-protection-cors-2-digitubes-a-decouper',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/2-digitubes-reutilisables-a-decouper-protection-cors_b8f36336-ca6a-47b8-88ab-8c432087cc42.jpg?v=1630349750"]','-1') ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Urgo Start 10cm*10cm','Urgo','Bien-être','-UrgoStart est indiqué pour le traitement des chroniques exsudatives (ulcères de jambe, escarres, plaies du pied diabétique…)

-Le pansement peut être posé sous compression élastique ou inélastique grâce à la rétention des exsudats dans le pansement

-Renouvellement atraumatique du pansement

-Accélère la cicatrisatio et améliore la qualité de vie du patient

-Stimulation des fibroblastes

-Inhibe l’excès de Métallo-Proteases Matricielles

-Traitement des plaies exsudatives

-Rétablit l’équilibre biochimique de la plaie',5700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgostart_07414d0a-9ea1-40f2-a728-4461165f74f5.jpg?v=1630349752',10,1,'6729085649071','39910401999023','https://beautymarket.ma/products/urgo-start-10cm-10cm',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/urgostart_07414d0a-9ea1-40f2-a728-4461165f74f5.jpg?v=1630349752"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
