INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Uriage Roséliane CC Cream SPF30 – 40 ml','Uriage','Visage','Problématique spécifique
Soins peaux sensibles à rougeurs à tendance couperosiques

