INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Uriage DÉPIDERM MOUSSE NETTOYANTE ÉCLAT 100ml','Uriage','Visage','Riche en Eau Thermale d’Uriage et en actifs perfecteurs d’éclat, cette mousse onctueuse nettoie et purifie la peau en douceur, tout en la laissant fraiche et lumineuse.

