INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Uriage BARIÉSUN FLUIDE MATIFIANT SPF50+ 50ml','Uriage','Solaires','Spécialement développé pour les peaux mixtes à grasses, ce fluide matifiant apporte une très haute protection contre les UVA, les UVB. Sa formule légère garantit un effet anti- brillance, une absorption rapide et une hydratation continue.

Protège contre les UV
Très haute protection UVA-UVB grâce à un complexe filtrant ultra–performant.

Matifie
Il apporte un effet matifiant durable grâce à l’extrait de Licorice, à l’action sébo-régulatrice.

Hydrate
Très hydratant, il détient des actifs limitant le dessèchement cutané.

Conseils d’utilisation :

Avant l’exposition, appliquer une dose suffisante pour bien couvrir la zone exposée, par exemple l’équivalent d’une cuillère à café de produit pour le visage et le cou. La réduction de cette quantité diminue le niveau de protection. Renouveler l’application fréquemment, surtout après avoir transpiré, nagé ou s’être essuyé. Même bien protégé, réduire au maximum l’exposition. Ne pas exposer les bébés et les jeunes enfants directement au soleil.',15900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FLUIDE.png?v=1754906696',10,1,'6729099051183','39910421037231','https://beautymarket.ma/products/uriage-bariesun-fluide-matifiant-spf50-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/FLUIDE.png?v=1754906696"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Uriage BARIÉSUN FLUIDE ULTRA LÉGER SPF50+ 30ml','Uriage','Solaires','Spécialement développé pour les peaux sensibles, ce fluide léger non parfumé apporte une très haute protection contre les UVA et les UVB. Sa texture ultra-fluide résistante à l’eau assure une pénétration rapide et un fini sec, sans effet blanc. Son format de poche le rend très pratique à utiliser en toute occasion !

Protège contre les UV

Son complexe de filtres apporte une très haute protection contre les UVA, les UVB et les radicaux libres. Ce soin garantit une large couverture UVB-UVA et une très haute tolérance.

CONSEILS D’UTILISATION :

Agiter avant emploi. Avant l’exposition, appliquer une dose suffisante pour bien couvrir la zone exposée, par exemple l’équivalent d’une cuillère à café de produit pour le visage et le cou. La réduction de cette quantité diminue le niveau de protection. Renouveler l’application fréquemment, surtout après avoir transpiré, nagé ou s’être essuyé. Même bien protégé, réduire au maximum l’exposition. Ne pas exposer les bébés et les jeunes enfants directement au soleil.',8900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ChatGPTImageJul3_2026_05_39_52PM.png?v=1783096795',10,1,'6729099149487','39910421135535','https://beautymarket.ma/products/uriage-bariesun-fluide-ultra-leger-spf50-30ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/ChatGPTImageJul3_2026_05_39_52PM.png?v=1783096795","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fr-fr-uriage-b-bariesun-3661434027994-en-variation-01-9.png?v=1783096670","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fluide50.png?v=1717425419"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('XEMOSE C8+ - SOIN PALPÉBRAL NOURRISSANT APAISANT','Uriage','Visage','Spécifiquement formulé pour les contours des yeux secs et sujets aux démangeaisons, ce soin apaise immédiatement et durablement les sensations de sécheresse, tiraillements et inconfort. Sa formule haute tolérance décongestionne, nourrit la peau et aide ainsi à restaurer la barrière cutanée.

Anti-grattage – Anti-sécheresse – Anti-récidive

Renforcement de la triple barrière de la peau.

Texture crème confortable, non collante, non parfumée.

Enfants, Adultes

