INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vichy Capital Soleil Soin anti-taches teinté 3-en-1 SPF 50+ – 50 ml','Vichy','Solaires','CAPITAL SOLEIL Soin Anti-Taches Teinté 3en1 protège, unifie et corrige le teint.
