INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('VITIS Dentifrice Orthodontic 100 ml – Dentifrice spécial appareils dentaires & soins-gencives','Vitis','Hygiène','VITIS Dentifrice Orthodontic 100 ml



