INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE Soleil des Vignes Fresh Fragrance 50ml','Caudalie','Autres soins','L''eau fraiche Soleil des Vignes Caudalie est la nouvelle fragrance de la gamme des eaux fraiches parfumées ! Non photosensibilisante, elle permet de se parfumer le corps et les cheveux d''un délicieux voile aux notes estivales.

