INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE VINOPURE GELEE NETTOYANTE PURIFIANTE - 150 ML','Caudalie','Visage','Premier geste beauté indispensable contre les imperfections, la Gelée Nettoyante Purifiante enrichie en acide salicylique naturel, Polyphénols de raisins et huiles essentielles bio* nettoie et purifie la peau sans la dessécher. Sa formule allie douceur et efficacité pour resserrer les pores, réduire l''excès de sébum et diminuer visiblement les imperfections.

Sa texture gélifiée laisse une sensation de fraîcheur et de propreté instantanée sur la peau.

Interprétation olfactive légère, 100% naturelle, issue du cocktail d''huiles essentielles qui délivre un souffle de fraîcheur à chaque application.

* Brevet déposé n°PCT/EP2018/050482.

Bénéfices

- Purifie
- Réduit les imperfections
- Resserre les pores
- Réduit l''excès de sébum

Formule :

98% d''ingrédients d''origine naturelle.
Non comédogène, testée dermatologiquement. Sans parfum synthétique ajouté, sans sulfates, sans savon, sans alcool.
Et comme tous les produits Caudalie, sans parabènes, phénoxyéthanol, phtalates, huiles minérales, ingrédients d''origine animale.',17000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/geleeeee_ec12c407-dc9f-4df6-a476-6b131ad513ba.png?v=1763822751',10,1,'6910671782063','40538805272751','https://beautymarket.ma/products/caudalie-vinopure-gelee-nettoyante-purifiante-150-ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/geleeeee_ec12c407-dc9f-4df6-a476-6b131ad513ba.png?v=1763822751"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE VINOPURE serum infusion anti inperfections 30ml','Caudalie','Cheveux','Concentré en acide salicylique naturel, polyphénols de raisins et huiles essentielles bios*, ce sérum à la texture légère fond au contact de la peau pour réduire visiblement les imperfections, resserrer les pores et affiner le grain de peau. Purifiée, la peau est douce et plus lumineuse.

Sa texture légère, gélifiée, le rend imperceptible, il fond directement sur la peau.

Interprétation olfactive légère, 100% naturelle, issue du cocktail d''huiles essentielles qui délivre un souffle de fraîcheur à chaque application.

Bénéfices

- Réduit les imperfections
- Affine le grain de peau
- Desincruste et resserre les pores
- Active l''éclat

Appliquer matin et soir sur le visage. Laisser infuser quelques minutes avant d’appliquer la crème.

Si la peau est trop sèche après application, limiter l’utilisation à une fois par jour. Éviter le contour des yeux.',39000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fdgtr.png?v=1759425189',10,1,'6910671880367','40538805502127','https://beautymarket.ma/products/caudalie-vinopure-serum-infusion-anti-imperfections',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fdgtr.png?v=1759425189"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('CAUDALIE VINOSCULPT Baume Corps Lift & Fermeté 250ml','Caudalie','Corps','Enrichi en Polyphénols de raisin anti-oxydants et en extrait d''iris raffermissant, le Baume Corps Lift & Fermeté agit simultanément sur les 4 zones clés de votre corps : bras, buste, ventre et fesses pour une peau plus ferme dès le premier mois d''utilisation*. La peau est lissée, tonifiée et visiblement raffermie. Le beurre de karité bio préserve l''hydratation de la peau, élément essentiel pour la souplesse de l''élastine.

Sa texture crème fouettée favorise le massage et laisse la peau douce, sans effet gras.

À l’application, on découvre une fragrance légère aux délicates notes de fleur d''oranger.

* Étude clinique, % de satisfaction, 28 jours, 21 volontaires. Testé sous contrôle dermatologique.

Bénéfices

- Raffermit
- Lisse
- Hydrate instantanément
- Parfume délicatement

Formule :

97% d''ingrédients d''origine naturelle.

Testé dermatologiquement. Convient aux peaux sensibles et aux femmes enceintes.

Et comme tous les produits Caudalie, sans parabènes, phénoxyéthanol, phtalates, huiles minérales, ingrédients d''origine animale.

Application

Appliquer matin et soir sur une peau propre et sèche et masser par mouvements circulaires sur les bras, le buste, le ventre et les fesses jusqu''à parfaite pénétration.',33000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/33F.jpg?v=1711640712',10,1,'6910671913135','40538805534895','https://beautymarket.ma/products/caudalie-vinosculpt-baume-corps-lift-fermete',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/33F.jpg?v=1711640712"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
