INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Macadamia Professional Ultra Rich REPAIR Oil Treatment','Macadamia','Cheveux','L’huile Ultra Rich pour cheveux drus/bouclés enrichie en PRO OIL COMPLEX, est une huile de soin nourrissante, non grasse, absorbée instantanément dans le cheveu pour offrir hydratation, souplesse, protection et brillance.

