INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REVITALASH Hi-Def Gel Fixateur de Sourcils DARK BROWN','RevitaLash','Visage','Notre gel novateur nourrit et dompte les sourcils indisciplinés tout en les sculptant et les fixant pour des sourcils plus beaux, plus définis. Le nouvel applicateur avec un embout peigne/brosse sculpte chaque poil, même les plus fins, pour créer des sourcils parfaitement dessinés

Utilisation

Étape 1 :

Utiliser l’embout peigne/brosse pour aligner les poils des sourcils et leur donner forme avec de petits mouvements vers le haut en suivant la forme de l’arcade sourcilière.

Étape 2 :

Utiliser l’embout brosse pour appliquer le gel par petites touches vers le haut, de l’intérieur vers l’extérieur, pour sculpter et définir les sourcils.

Étape 3 :

Parfaire la forme avec l''embout peigne/brosse.',32300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/product_7310260c-1705-4694-844f-3e5fd94d9ff1.jpg?v=1630350721',10,1,'6910680039599','40538822049967','https://beautymarket.ma/products/revitalash-hi-def-gel-fixateur-de-sourcils-dark-brown',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/product_7310260c-1705-4694-844f-3e5fd94d9ff1.jpg?v=1630350721"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
