INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Cetaphil Sun Light Gel SPF50+ – Gel solaire léger 50 ml','Cetaphil','Solaires','Gel solaire léger et non gras, sans parfum ni émulsifiants, pour les peaux mixtes, grasses et très sensibles ou sujettes aux allergies solaires. Les points forts : très haute protection UVA, UVB et IR (SPF50+), gel léger et non gras, absorption rapide, convient aux allergies solaires et à l’acné de Majorque, sans parfum, sans émulsifiants, très résistant à l’eau, même salée. Gamme Cetaphil Sun, laboratoire Galderma.

Les bienfaits

Très haute protection UVA, UVB et IR (SPF50+)

Gel léger et non gras, absorption rapide

Convient aux allergies solaires et à l’acné de Majorque

Sans parfum, sans émulsifiants

Très résistant à l’eau, même salée

Hypoallergénique, non comédogène

Mode d’emploi

Appliquer généreusement et uniformément avant l’exposition au soleil. Renouveler l’application fréquemment, notamment après la baignade, la transpiration ou le séchage.

Précautions

Éviter le contact avec les yeux. Une application répétée ne prolonge pas la durée d’exposition maximale au soleil. Ne pas rester trop longtemps au soleil, même avec une protection.',16500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1ZOoRVT7amQB_-iRizBbFxrttG2sCgCd-_s0.png?v=1793463916',10,1,'7333897961647','41910060548271','https://beautymarket.ma/products/cetaphil-sun-light-gel-spf50-50ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/1ZOoRVT7amQB_-iRizBbFxrttG2sCgCd-_s0.png?v=1793463916"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
