INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP dépi-gel nettoyant éclaircissant 200 ml','DCP','Visage','DCP DEPI-GEL nettoie, éclaircit et unifie le teint. La peau devient fraîche, pure et lumineuse et retrouve son éclat et transparence.



Formulé avec une combinaison spécifique à base d''actifs dépigmentants, DCP DEPI-GEL éclaircit et unifie le teint et favorise à diminuer considérablement l''apparence des tâches brunes. Grâce à ses microbiles de silice, Il exfolie en douceur et nettoie profondément en laissant la peau fraîchement nettoyée et douce avec un teint uniforme et lumineux.',18000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPP.png?v=1715940070',10,1,'7396750229679','42110334337199','https://beautymarket.ma/products/dcp-depi-gel-nettoyant-eclaircissant-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPP.png?v=1715940070"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP DEPI PLUS INTIMATE LAIT ÉCLAIRCISSANT 200 ML','DCP','Corps','DCP DEP-PLUS INTIME est un conçu pour éclaircir la peau des zones intimes. Soigneusement formulé  avec des principes actifs de haute tolérance pour les parties les plus sensibles du corps. DCP DEPHPLUS INTIME type d’améliore la dépigmentation de la zone intime et réduite la méta synthèse efficace de la mélanine. Grâce à sa formule riche il éclaircit efficacement et assure un confort et une hydratation tout au long de la journée.Les zones concernées : Entre jambes – aisselles

CONSEILS D''UTILISATION :

appliquez une fine couche de DCP DEP PLUS INTIME sur la zone et convenablement nettoyée et séchée une à deux fois par jour',35000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPPP.png?v=1692785852',10,1,'7396750590127','42110336663727','https://beautymarket.ma/products/dcp-depi-plus-intimate-lait-eclaircissant-200-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPPP.png?v=1692785852"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP EMULSION DS+ 40 ML','DCP','Cheveux','DCP EMULSION DS+ nécessite sébum et kératinisation, élimine pellicules, pellicules et rougeurs. Grâce à ses actifs antifongiques et anti-inflammatoires, DCP EMULSION DS+ limite la prolifération de Malassezia et soulage les sensations d''inconfort. Formulée avec des actifs haute tolérance, DCP EMULSION DS+ convient à toutes les peaux les plus sensibles et délicates. Visage , corps et cuir chevelu',11900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LKL.png?v=1692785961',10,1,'7396750721199','42110340366511','https://beautymarket.ma/products/dcp-emulsion-ds-40-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/LKL.png?v=1692785961"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP SOIN PIED KPP Soin Mains & Pieds 100ml','DCP','Corps','DCP KPP SOIN, est un soin traitant des kératodermies palmo plantaires, des callosités, des cornes et des rugosité.

DCP KPP SOIN assouplis les plantes des pieds et les paumes des mains et aide à éliminer soigneusement les callosités, les durillons et les cornes.',14400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/DCP-KPP-SOIN-main-et-pied-595x600.webp?v=1667560976',10,1,'7396750917807','42110341382319','https://beautymarket.ma/products/dcp-kpp-soin-mains-pieds-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/DCP-KPP-SOIN-main-et-pied-595x600.webp?v=1667560976"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP LOTION BHA 100ml','DCP','Visage','Cette lotion douce, légère, exfolie rapidement les cellules mortes à la fois à la surface de la peau et à l’intérieur des pores pour faire ressortir l’éclat, la netteté et la luminosité du teint. le BHA (acide salicylique) qu’elle contient régule les excès de sébum et contribue à réduire les points noirs, les taches et les rougeurs. Elle agit sur le spore dilatés',13900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/dcp-lotion-bha-100ml.jpg?v=1667561088',10,1,'7396751311023','42110342037679','https://beautymarket.ma/products/dcp-lotion-bha-100ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/dcp-lotion-bha-100ml.jpg?v=1667561088"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DCP LOTION DS + 100 ML','DCP','Cheveux','DCP LOION DS+ est un spray kérato-régulateur qui régule le sébum et favorise l’élimination des squames et des pellicules des graminées.

Richement formulée avec des actifs hautement performants pour apaiser les démangeaisons et les irritations, DCP LOTION DS+ assure une action antifongique, anti-inflammatoire.

Grâce à sa forme spray, il est un moyen à appliquer, ne graisse pas les cheveux et permet au cuir chevelu de retrouver son équilibre naturel et sain.



CONSEILS D''UTILISATION :



Appliquer quotidiennement DCP LOTION DS- sur le cuir chevelu et laisser agir deux à trois jours.

Pour un excellent résultat, laver après avec DCP Base lavante DS+.',13500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPDS.png?v=1692783777',10,1,'7396751540399','42110342725807','https://beautymarket.ma/products/dcp-lotion-ds-100-ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/DCPDS.png?v=1692783777"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Remescar Correcteur de rides instantané','Remescar','Visage','La crème anti-rides instantanée de Remescar réduit immédiatement la visibilité des rides et des ridules. Appliquez la crème, patientez quelques instants et vous constaterez une différence dès la première application. Le résultat reste visible jusqu’à 10 heures. Cette crème se combine facilement avec le maquillage.',44500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/120466649_MCM_PACK_146429.webp?v=1667646052',10,1,'7397242273967','42112976847023','https://beautymarket.ma/products/remescar-instant-wrinkle-corrector',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/120466649_MCM_PACK_146429.webp?v=1667646052"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Remescar Poches & Cernes','Remescar','Visage','Remescar Poches & Cernes produit un effet instantané en raison de sa technologie révolutionnaire EYESYL qui cible immédiatement les poches et cernes sous les yeux, en utilisant une combinaison unique de minéraux d’argile et un complexe bi-peptide qui entraînera un fort resserrement de la peau, une diminution de l’accumulation de liquide sous les yeux et une pause micro-musculaire.',44500,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/https___remescar.com_volumes_products_Remescar_Packshots_RSDC02_NL.f1632473771.webp?v=1667646199',10,1,'7397242437807','42112977076399','https://beautymarket.ma/products/remescar-poches-cernes',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/https___remescar.com_volumes_products_Remescar_Packshots_RSDC02_NL.f1632473771.webp?v=1667646199"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Remescar Sérum à la Vitamine C','Remescar','Visage','Remescar Sérum réparateur à la Vitamine C & acide hyaluronique a pour but de réduire les taches foncées et l’hyperpigmentation. Il aide à protéger la peau contre les rayons UV et à réparer les dommages causés par le soleil. L’objectif principal est d’obtenir une peau plus saine et plus uniforme en réduisant naturellement les rougeurs et les impuretés.

L’utilisation d’un complexe vitamine C 45 % puissant et stabilisé permet d’obtenir des avantages et des résultats optimaux',29900,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/remiscaryy.jpg?v=1766665242',10,1,'7397242732719','42112977731759','https://beautymarket.ma/products/remescar-serum-a-la-vitamine-c',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/remiscaryy.jpg?v=1766665242","https://cdn.shopify.com/s/files/1/0572/7938/1679/files/IUYYJ.jpg?v=1766665242"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('REGFACE SOIN SPECIFIQUE ANTI-TÂCHES BRUNES','Regface','Visage','Pour qui ?

Hyperpigmentation cutanée du visage et du décolleté

(Taches pigmentaires , peau affinée)

Conseils d''utilisation :

Soin spécifique anti-taches brunes

Appliquer sur le visage et/ou le décolleté matin et soir en massant légèrement,

REGFACE doit être utilisé le matin avant le maquillage et le soir sur une peau

démaquillée et propre,

Des actifs essentiels :

Extraits de fleurs de Pâquerette Bellis Pernnis , lys de mer Pancratium Maritimum et

Marron d''Inde :

favorisent la dépigmentation en inhibant la synthèse et la migration de mélanine,

Extraits d''algue verte Ulva Lactuca, lipoaminoacides biovecteurs d''isoleucine , Chlorella

Vulgaris et Porphyridium Cruentum :

redensifient la peau,',22700,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/regface-regface-soin-specifique-anti-taches-brunes-50-ml-cremes-depigmentantes.jpg?v=1718096211',10,1,'7398788923567','42119109279919','https://beautymarket.ma/products/regface-soin-specifique-anti-taches-brunes',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/regface-regface-soin-specifique-anti-taches-brunes-50-ml-cremes-depigmentantes.jpg?v=1718096211"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
