INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Vitamine C 60 gélules','WSN Natural','Bien-être','La vitamine C est une substance organique non calorique, essentielle au métabolisme de l’organisme humaine.',7125,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/WSN_Natural.Vitamin_C_SD.png?v=1668764504',10,1,'7409170677935','42146153463983','https://beautymarket.ma/products/vitamine-c-60-gelules',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/WSN_Natural.Vitamin_C_SD.png?v=1668764504"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HYDRA PHYT’S VITAMINE E 36 CAPSULES','Hydra Phyt''s','Bien-être','La Vitamine E est une vitamine et un nutriment essentielle pour notre corps.

Elle possède de nombreuses vertus très bénéfiques pour notre santé grâce a son action sur les membranes de toutes les cellules de notre organisme.

Antioxydant très puissant, la vitamine E 1000ui agit efficacement contre les dommages des radicaux libres responsables du vieillissement de la peau.

Ainsi, elle est reconnue comme la « vitamine anti-âge ».

Son action protège nos cellules en combattant les radicaux libres responsables du vieillissement des cellules et donc de la peau.

Par cette action, elle permet de ralentir les effets du vieillissement des cellules et donc de maintenir une peau jeune et en bonne sante.',9300,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HYDRAE.jpg?v=1755534240',10,1,'7409171169455','42146155102383','https://beautymarket.ma/products/hydra-phyt-s-vitamine-e',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/HYDRAE.jpg?v=1755534240"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('SVR Baume Lavant Mains Sensibles 400ML','SVR','Corps','Assainissant, hydratant. Elimine les bactéries en un lavage. Un baume lavant ultra-crémeux spécifiquement développé pour les mains sensibles et sèches de toute la famille. Sa formule ultra clean, sans savon ni sulfates, composée de tensioactifs doux permet de capter les corps étrangers, les impuretés et les bactéries à la surface de la peau pour les éliminer délicatement grâce au lavage.
Sa texture onctueuse enrichie en glycérine et délicatement parfumée se transforme en mousse généreuse pour envelopper les mains dans un cocon de douceur. Les mains sont propres, douces, les grattages et les inconforts disparaissent immédiatement.Promis, se laver les mains va devenir un vrai moment de plaisir !',9000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MAINSSENSSIBLES.png?v=1689175568',10,1,'7410272633007','42150679150767','https://beautymarket.ma/products/svr-baume-lavant-mains-sensibles-400ml',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/MAINSSENSSIBLES.png?v=1689175568"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Revitalash Au Naturale Collection pour les SourCils','RevitaLash','Maquillage','Laissez de côté le maquillage cet été avec le Coffret Au Naturale ! Avec notre soin incontournable RevitaBrow® Advanced primé et notre nouveau masque soin Lash & Brow Masque révolutionnaire, vos cils et sourcils seront naturellement magnifiques. Le Coffret comprend: • RevitaBrow® Advanced 3.0 mL • Lash & Brow Masque 5.0 mL • Pince à Epiler • Trousse de maquillage en cuir végan',144000,'https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fyftyu.png?v=1696259737',10,1,'7410684166319','42152539848879','https://beautymarket.ma/products/revitalash-au-naturale-collection-pour-les-cils',0,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/files/fyftyu.png?v=1696259737"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Camomilla Blu Organic Eco-bio Nettoyant Intime pH5.5 300ml','Camomilla Blu','Bébé & Maman','Nettoyant intime éco-bio idéal pour une hygiène quotidienne délicate adapté à toute la famille. Contient de l’aloe vera et des extraits enzymatiques de riz et de camomille issus de l’agriculture biologique. Formulé à pH 5,5, il forme une mousse légère et laisse une agréable sensation de fraîcheur sur la peau. Lutte contre les irritations et le dessèchement de la peau.

Indication :
Hygiène intime quotidienne des sujets à la peau sensible et irritable de toute la famille.

Propriétés :
– 0% SLES/SLS, parabènes, silicones, allergènes de parfum, isothiazolinones, colorants
– pH 5,5
– Certifié Bio
– Fabriqué en Italie

Conseils d’utilisation :
Appliquez une petite quantité de produit sur les zones concernées, puis rincez. A utiliser tel quel ou dilué avec de l’eau. Pour usage externe.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/9965-7-600x600.png?v=1760615660',10,1,'7413755412655','42163450380463','https://beautymarket.ma/products/camomilla-blu-organic-eco-bio-nettoyant-intime-ph5-5-300ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/9965-7-600x600.png?v=1760615660"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('Camomilla Blu Lovely Girl Nettoyant Intime Ph 5.5 300ml','Camomilla Blu','Corps','Nettoyant formulé avec des tensioactifs délicats, idéal pour l’hygiène intime quotidienne des filles en âge pré-adolescent. Enrichi en protéines de lait et en extrait de camomille, il a une action adoucissante laissant la peau hydratée.',9400,'https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Camomilla-Blu-Lovely-girl-Nett-intime-ph-5.5-300ml.webp?v=1753879311',10,1,'7413756133551','42163451527343','https://beautymarket.ma/products/camomilla-blu-lovely-girl-nettoyant-intime-ph-5-5-300ml',1,'["https://cdn.shopify.com/s/files/1/0572/7938/1679/products/Camomilla-Blu-Lovely-girl-Nett-intime-ph-5.5-300ml.webp?v=1753879311"]',NULL) ON CONFLICT(source_variant_id) DO NOTHING;
