INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('HT CEUTIC crème régénérante 50ML','HT Ceutic','Visage','HTCEUTIC CRÈME RÉGÉNÉRANTE à base de Vit-A-Like est un soin quotidien qui possède des propriétés anti-âge et aide à stimuler le renouvellement cellulaire et la synthèse du collagène.
