INSERT INTO products(name,brand,category,description,price,image,stock,active,source_product_id,source_variant_id,source_url,source_available,images_json,sku) VALUES ('DERMACEUTIC FOAMER 15 100 ML','Dermaceutic','Visage','Dermaceutic Foamer 15 élimine les impuretés et les cellules mortes en laissant la peau lisse et soyeuse.
